  display: block;
  margin-bottom: 3px;
  color: #177245;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.tracking-page__header h1 {
  margin: 0 0 4px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
}

.tracking-page__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

/*==================================================
| Search Card
==================================================*/
.tracking-search-card {
  margin-bottom: 15px;
  padding: 18px;
  border: 1px solid rgba(23, 114, 69, 0.1);
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(23, 114, 69, 0.055), #fff);
  display: flex;
  align-items: flex-start;
  gap: 13px;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

.tracking-search-card__icon {
  width: 43px;
  height: 43px;
  flex: 0 0 43px;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.tracking-search-card__icon i {
  font-size: 20px;
}

.tracking-search-card__content {
  min-width: 0;
  flex: 1;
}

.tracking-search-card__content h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
}

.tracking-search-card__content > p {
  margin: 0 0 13px;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

.tracking-search-form {
  width: 100%;
  display: flex;
  align-items: stretch;
  gap: 8px;
}

.tracking-search-input {
  position: relative;
  flex: 1;
  min-width: 0;
}

.tracking-search-input > i {
  position: absolute;
  top: 50%;
  left: 12px;
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  transform: translateY(-50%);
  pointer-events: none;
}

.tracking-search-input input {
  width: 100%;
  height: 42px;
  padding: 0 12px 0 35px;
  border: 1px solid rgba(16, 26, 35, 0.1);
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.tracking-search-input input::placeholder {
  color: rgba(85, 85, 85, 0.18);
}

.tracking-search-input input:focus {
  border-color: rgba(23, 114, 69, 0.35);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

.tracking-search-btn {
  height: 42px;
  padding: 0 14px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}
.tracking-search-btn i {
  font-size: 14px;
}
.tracking-search-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  box-shadow: 0 5px 14px rgba(23, 114, 69, 0.12);
}

.tracking-search-help {
  margin-top: 8px;
  display: flex;
  align-items: center;
  gap: 5px;
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
  line-height: 1.35;
}
.tracking-search-help i {
  color: #177245;
  font-size: 14px;
}

/*==================================================
| Statistics
==================================================*/
.tracking-stats {
