  flex-direction: column;
  gap: 2px;
}

.tracking-stat-card span {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  line-height: 1.3;
}

.tracking-stat-card strong {
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.2;
}

/*==================================================
| Main Card
==================================================*/
.tracking-card {
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
