  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.tracking-status-card__icon i {
  font-size: 21px;
}

/*==================================================
| Progress
==================================================*/
.tracking-status-card__progress {
  padding: 4px 17px 16px;
}

.tracking-progress {
  position: relative;
}

.tracking-progress__line {
  position: absolute;
  top: 16px;
  left: 7%;
  width: 86%;
  height: 2px;
  background: rgba(16, 26, 35, 0.09);
}

.tracking-progress__fill {
  display: block;
  height: 100%;
  background: #177245;
}

.tracking-progress__steps {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
}

.tracking-progress-step {
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 6px;
  color: rgba(85, 85, 85, 0.13);
  text-align: center;
}

.tracking-progress-step > span {
  width: 32px;
  height: 32px;
  border: 2px solid #dce0e3;
  border-radius: 50%;
  background: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.tracking-progress-step > span i {
  font-size: 13px;
}

.tracking-progress-step strong {
  color: inherit;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
}

.tracking-progress-step--completed {
  color: #177245;
}

.tracking-progress-step--completed > span {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

.tracking-progress-step--active {
  color: #177245;
}

.tracking-progress-step--active > span {
  border-color: #177245;
  color: #177245;
}

/*==================================================
| Status Footer
==================================================*/
.tracking-status-card__footer {
  padding: 11px 17px;
  border-top: 1px solid rgba(16, 26, 35, 0.06);
  background: rgba(255, 255, 255, 0.55);
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.tracking-status-card__footer > div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tracking-status-card__footer span {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  line-height: 1.3;
}

.tracking-status-card__footer strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
}

/*==================================================
| General Card
==================================================*/
.tracking-details-card {
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
}

.tracking-details-card__header {
  min-height: 57px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.065);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.tracking-details-card__header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
}

.tracking-details-card__header p {
  margin: 0;
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
  line-height: 1.4;
}

/*==================================================
| Timeline
==================================================*/
.tracking-timeline {
  padding: 17px 18px 6px;
}

.tracking-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  padding-bottom: 21px;
}

.tracking-timeline-item:last-child {
  padding-bottom: 7px;
}

.tracking-timeline-item:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 34px;
  left: 16px;
  width: 1px;
  height: calc(100% - 22px);
  background: #e4e7e9;
}

.tracking-timeline-item--current:not(:last-child)::before {
  background: rgba(23, 114, 69, 0.2);
}

.tracking-timeline-item__indicator {
  position: relative;
  z-index: 2;
}

.tracking-timeline-item__indicator > span {
  width: 33px;
  height: 33px;
  border: 1px solid #dfe3e6;
  border-radius: 50%;
  background: #fff;
  color: rgba(85, 85, 85, 0.8);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.tracking-timeline-item__indicator > span i {
  font-size: 14px;
}

.tracking-timeline-item--current .tracking-timeline-item__indicator > span {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}

.tracking-timeline-item__content {
  min-width: 0;
  padding-top: 2px;
}

.tracking-timeline-item__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 15px;
}

.tracking-timeline-item__top h3 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}

.tracking-timeline-item__top span {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  line-height: 1.3;
}

.tracking-timeline-item__top time {
  flex: 0 0 auto;
  color: rgba(85, 85, 85, 0.13);
  font-size: 14px;
  line-height: 1.3;
  white-space: nowrap;
}

.tracking-timeline-item__content > p {
  max-width: 700px;
  margin: 7px 0 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*==================================================
| Info Grid
==================================================*/
.tracking-info-grid {
  padding: 15px 16px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
}

.tracking-info-item {
  min-width: 0;
  padding: 11px 12px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
}

.tracking-info-item:nth-last-child(-n+2) {
  border-bottom: 0;
}

.tracking-info-item span {
  display: block;
  margin-bottom: 3px;
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  line-height: 1.3;
}

.tracking-info-item strong {
  display: block;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*==================================================
| Client
==================================================*/
.tracking-client {
  padding: 14px 15px;
  display: flex;
  align-items: center;
  gap: 9px;
}

.tracking-client__avatar {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
}

.tracking-client__info {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.tracking-client__info strong {
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tracking-client__info span {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
}

.tracking-client__details {
  padding: 0 15px 13px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tracking-client__details > div {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}

.tracking-client__details i {
  color: #177245;
  font-size: 14px;
}

.tracking-client__details span {
  overflow: hidden;
  color: #555555;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*==================================================
| Route
==================================================*/
.tracking-route {
  padding: 15px 16px;
}

.tracking-route__item {
  display: flex;
  align-items: center;
  gap: 9px;
}

.tracking-route__marker {
  width: 31px;
  height: 31px;
  flex: 0 0 31px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.tracking-route__marker i {
  font-size: 14px;
}

.tracking-route__marker--origin {
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}

.tracking-route__marker--destination {
  background: #edf3ff;
  color: #4a70ad;
}

.tracking-route__item > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.tracking-route__item span {
  color: rgba(85, 85, 85, 0.12);
  font-size: 14px;
}

.tracking-route__item strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.tracking-route__item small {
  color: rgba(85, 85, 85, 0.13);
  font-size: 14px;
}

.tracking-route__line {
  width: 1px;
  height: 22px;
  margin: 2px 0 2px 15px;
  background: #dfe3e6;
}

/*==================================================
| Package
==================================================*/
.tracking-package-list {
  padding: 4px 15px 8px;
}

.tracking-package-list > div {
  min-height: 45px;
  padding: 8px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.tracking-package-list > div:last-child {
  border-bottom: 0;
}

.tracking-package-list span {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
}

.tracking-package-list strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}

/*==================================================
| Actions
==================================================*/
.tracking-actions {
  padding: 4px 8px 8px;
}

.tracking-action {
  width: 100%;
  min-height: 43px;
  padding: 5px 7px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  color: #555555;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s ease;
}

.tracking-action:last-child {
  border-bottom: 0;
}

.tracking-action > span:nth-child(2) {
  flex: 1;
}

.tracking-action > i {
  color: rgba(85, 85, 85, 0.12);
  font-size: 14px;
}

.tracking-action:hover {
  color: #177245;
}

.tracking-action__icon {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.tracking-action__icon i {
  font-size: 14px;
}

/*==================================================
| Responsive - LG
==================================================*/
@media (min-width: 992px) and (max-width: 1199px) {
  .tracking-details-layout {
    grid-template-columns: minmax(0, 1fr) 270px;
  }
}
/*==================================================
| Responsive - MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .tracking-details-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .tracking-details-header__actions {
    width: 100%;
    justify-content: flex-start;
  }
  .tracking-details-layout {
    grid-template-columns: 1fr;
  }
  .tracking-details-sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .tracking-details-sidebar .tracking-details-card:last-child {
    grid-column: 1/-1;
  }
}
/*==================================================
| Responsive - XS
==================================================*/
@media (max-width: 767px) {
  .tracking-details-title {
    align-items: flex-start;
  }
  .tracking-details-title__icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
  }
  .tracking-details-title h1 {
    font-size: 20px;
  }
  .tracking-details-header__actions {
    align-items: stretch;
    flex-direction: column;
  }
  .tracking-details-action {
    width: 100%;
  }
  .tracking-status-card__top {
    padding: 14px;
  }
  .tracking-status-card__progress {
    padding: 4px 10px 14px;
  }
  .tracking-progress__line {
    left: 8%;
    width: 84%;
  }
  .tracking-progress-step strong {
    font-size: 14px;
  }
  .tracking-status-card__footer {
    grid-template-columns: 1fr;
    gap: 9px;
    padding: 10px 14px;
  }
  .tracking-details-card__header {
    padding: 12px 13px;
  }
  .tracking-timeline {
    padding: 14px 13px 5px;
  }
  .tracking-timeline-item__top {
    align-items: flex-start;
    flex-direction: column;
    gap: 4px;
  }
  .tracking-info-grid {
    grid-template-columns: 1fr;
    padding: 10px 12px;
  }
  .tracking-info-item {
    padding: 9px 4px;
  }
  .tracking-info-item:nth-last-child(-n+2) {
    border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  }
  .tracking-info-item:last-child {
    border-bottom: 0;
  }
  .tracking-details-sidebar {
    grid-template-columns: 1fr;
  }
  .tracking-details-sidebar .tracking-details-card:last-child {
    grid-column: auto;
  }
}
/*================================*
* Users - All Users
*=================================*/
.users-page {
  width: 100%;
}

/*================================*
* Page Header
*=================================*/
.users-page__header {
  margin-bottom: 28px;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .users-page__header {
    margin-bottom: 24px;
  }
}
@media (max-width: 767px) {
  .users-page__header {
    margin-bottom: 20px;
  }
}

.users-page__header-content {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 30px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .users-page__header-content {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }
}

.users-page__heading .users-page__eyebrow {
  display: inline-block;
  margin-bottom: 8px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.users-page__heading h1 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
}
@media (max-width: 767px) {
  .users-page__heading h1 {
    font-size: 22px;
  }
}
.users-page__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Header Actions
*=================================*/
.users-page__actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}
@media (max-width: 767px) {
  .users-page__actions {
    width: 100%;
  }
}

.users-filter-btn,
.users-primary-btn {
  min-height: 42px;
  padding: 0 16px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: border-color 0.2s ease, background-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
}
.users-filter-btn i,
.users-primary-btn i {
  font-size: 18px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .users-filter-btn,
  .users-primary-btn {
    min-height: 40px;
    padding: 0 14px;
  }
}
@media (max-width: 767px) {
  .users-filter-btn,
  .users-primary-btn {
    flex: 1;
  }
}

.users-filter-btn {
  border: 1px solid #ddd;
  background: #fff;
  color: #0D2B5A;
  cursor: pointer;
}
.users-filter-btn:hover, .users-filter-btn.active {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
}

.users-primary-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.users-primary-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
  box-shadow: 0 5px 15px rgba(23, 114, 69, 0.18);
}

/*================================*
* Statistics
*=================================*/
.users-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  margin-bottom: 24px;
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .users-stats {
    gap: 16px;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .users-stats {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .users-stats {
    gap: 14px;
  }
}
@media (max-width: 767px) {
  .users-stats {
    grid-template-columns: 1fr;
    gap: 12px;
    margin-bottom: 18px;
  }
}

.user-stat-card {
  min-width: 0;
  padding: 20px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
  display: flex;
  align-items: center;
  gap: 14px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.user-stat-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 7px 20px rgba(16, 26, 35, 0.06);
}
@media (min-width: 992px) and (max-width: 1199px) {
  .user-stat-card {
    padding: 18px;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .user-stat-card {
    padding: 16px;
  }
}
@media (max-width: 767px) {
  .user-stat-card {
    padding: 15px;
  }
}

.user-stat-card__icon {
  width: 47px;
  height: 47px;
  border-radius: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 47px;
}
.user-stat-card__icon i {
  font-size: 22px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .user-stat-card__icon {
    width: 43px;
    height: 43px;
    flex-basis: 43px;
  }
  .user-stat-card__icon i {
    font-size: 20px;
  }
}

.user-stat-card__icon--total {
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
}

.user-stat-card__icon--active {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}

.user-stat-card__icon--admins {
  background: rgba(255, 193, 7, 0.12);
  color: rgba(255, 193, 7, 0.15);
}

.user-stat-card__icon--online {
  background: rgba(13, 202, 240, 0.11);
  color: rgba(13, 202, 240, 0.15);
}

.user-stat-card__content {
  min-width: 0;
}
.user-stat-card__content span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
}
.user-stat-card__content strong {
  display: block;
  margin-bottom: 5px;
  color: #0D2B5A;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.2;
}
@media (min-width: 768px) and (max-width: 991px) {
  .user-stat-card__content strong {
    font-size: 22px;
  }
}
.user-stat-card__content small {
  display: flex;
  align-items: center;
  gap: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.user-stat-card__content small i {
  color: #198754;
  font-size: 14px;
}

/*================================*
* Filter Panel
*=================================*/
.users-filter-panel {
  display: none;
  margin-bottom: 20px;
  padding: 20px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
  animation: usersFilterShow 0.2s ease;
}
.users-filter-panel.is-open {
  display: block;
}
@media (max-width: 767px) {
  .users-filter-panel {
    padding: 16px;
    margin-bottom: 16px;
    border-radius: 10px;
  }
}

@keyframes usersFilterShow {
  from {
    opacity: 0;
    transform: translateY(-5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
.users-filter-group label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}

.users-filter-input {
  position: relative;
}
.users-filter-input i {
  position: absolute;
  left: 13px;
  top: 50%;
  transform: translateY(-50%);
  color: #555555;
  font-size: 18px;
  pointer-events: none;
}
.users-filter-input input {
  width: 100%;
  height: 42px;
  padding: 0 13px 0 40px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s ease;
}
.users-filter-input input:focus {
  outline: none;
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}
.users-filter-input input::placeholder {
  color: rgba(85, 85, 85, 0.65);
}

.users-filter-group select {
  width: 100%;
  height: 42px;
  padding: 0 12px;
  border: 1px solid #ddd;
