}

/*==============================================================
* Edit User Danger Box
*==============================================================*/
.edit-user-danger-box {
  padding: 15px;
  border: 1px solid rgba(220, 53, 69, 0.12);
  border-radius: 9px;
  background: rgba(220, 53, 69, 0.025);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
}
.edit-user-danger-box__icon {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 34px;
}
.edit-user-danger-box__icon i {
  font-size: 16px;
}
.edit-user-danger-box > div:not(.edit-user-danger-box__icon) {
  min-width: 0;
}
.edit-user-danger-box > div:not(.edit-user-danger-box__icon) strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}
.edit-user-danger-box > div:not(.edit-user-danger-box__icon) p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
@media (max-width: 767px) {
  .edit-user-danger-box {
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
  }
  .edit-user-danger-box .edit-user-delete-btn {
    grid-column: 1/-1;
    width: 100%;
  }
}

