}
body.dark-mode .theme-toggle .dark-icon,
body.dark-mode .theme-toggle .dark-text {
  display: inline-flex;
}

/* =========================================================
   Language Dropdown
========================================================= */
.language-dropdown {
  position: relative;
}

.language-toggle {
  min-height: 40px;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 11px;
  border: 1px solid #e1e5e9;
  border-radius: 8px;
  background: #fff;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}
.language-toggle:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.language-toggle i:first-child {
  font-size: 16px;
}
.language-toggle i:last-child {
  font-size: 16px;
}

.language-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 50;
  width: 170px;
  padding: 6px;
  border: 1px solid #e7eaed;
  border-radius: 9px;
  background: #fff;
  box-shadow: 0 10px 30px rgba(16, 26, 35, 0.1);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-5px);
  transition: opacity 0.2s ease, visibility 0.2s ease, transform 0.2s ease;
}
.language-menu.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.language-option {
