  color: #555555;
  font-size: 14px;
  text-align: left;
  cursor: pointer;
  transition: all 0.2s ease;
}
.language-option i {
  display: none;
  color: #177245;
  font-size: 16px;
}
.language-option:hover {
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}
.language-option.active {
  color: #177245;
  background: rgba(23, 114, 69, 0.07);
}
.language-option.active i {
  display: inline-flex;
