  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.inline-setting p {
  margin: 0;
  color: #858c94;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   Switch
========================================================= */
.switch {
  position: relative;
  width: 44px;
  height: 24px;
  flex: 0 0 44px;
  display: inline-block;
  cursor: pointer;
}
.switch input {
  width: 0;
  height: 0;
  opacity: 0;
}
.switch input:checked + .slider {
  background: #177245;
}
.switch input:checked + .slider::before {
  transform: translateX(20px);
}
.switch .slider {
  position: absolute;
  inset: 0;
  border-radius: 50px;
  background: #cfd4da;
  transition: background 0.2s ease;
}
.switch .slider::before {
  content: "";
  position: absolute;
  width: 18px;
  height: 18px;
  top: 3px;
  left: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.16);
  transition: transform 0.2s ease;
}

/* =========================================================
   Actions
========================================================= */
.settings-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: 4px;
}

.cancel-button,
.save-button {
  min-height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 9px 17px;
  border-radius: 8px;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
}

.cancel-button {
  border: 1px solid #e0e4e8;
  background: #fff;
  color: #646b73;
}
.cancel-button:hover {
  border-color: #d2d7dc;
  background: #f7f8f9;
}

.save-button {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.save-button:hover {
  border-color: rgba(23, 114, 69, 0.05);
  background: rgba(23, 114, 69, 0.05);
}

