/* =========================================================
   Audit Logs Page
========================================================= */
.audit-logs-page {
  width: 100%;
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px;
}
.audit-logs-page * {
  box-sizing: border-box;
}
.audit-logs-page button,
.audit-logs-page input,
.audit-logs-page select {
  font-family: inherit;
}

/* =========================================================
   Header
========================================================= */
.audit-header {
  margin-bottom: 24px;
}

.audit-header-content {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}

.audit-header-text h1 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.audit-header-text p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   Summary Cards
========================================================= */
.audit-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 20px;
}

.summary-card {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  padding: 18px;
  border: 1px solid #e8ebef;
  border-radius: 11px;
  background: #fff;
  box-shadow: 0 4px 18px rgba(16, 26, 35, 0.04);
}

.summary-icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}
.summary-icon.success {
  background: rgba(25, 135, 84, 0.08);
  color: #198754;
}
.summary-icon.warning {
  background: rgba(255, 193, 7, 0.1);
  color: #c58b00;
}
.summary-icon.danger {
  background: rgba(220, 53, 69, 0.08);
  color: #dc3545;
}

.summary-content {
  min-width: 0;
}
.summary-content span {
  display: block;
  margin-bottom: 3px;
  color: #7d858d;
  font-size: 14px;
  line-height: 1.4;
}
.summary-content strong {
  display: block;
  color: #0D2B5A;
  font-size: 20px;
  line-height: 1.3;
  font-weight: 700;
}

/* =========================================================
   Common Card
========================================================= */
.audit-card {
  margin-bottom: 20px;
  overflow: hidden;
  border: 1px solid #e8ebef;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 4px 18px rgba(16, 26, 35, 0.04);
}

.audit-card-header,
.logs-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 20px 22px;
  border-bottom: 1px solid #edf0f3;
}
.audit-card-header h2,
.logs-card-header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.audit-card-header p,
.logs-card-header p {
  margin: 0;
  color: #7b838b;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   Filters
========================================================= */
.audit-filter-body {
  padding: 20px 22px;
}

.audit-filter-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr) auto;
  align-items: end;
  gap: 14px;
}

.filter-field {
  min-width: 0;
}
.filter-field label {
  display: block;
  margin-bottom: 7px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.search-input {
  position: relative;
}
.search-input i {
  position: absolute;
  top: 50%;
  left: 12px;
  z-index: 1;
  color: #9299a0;
  font-size: 16px;
  transform: translateY(-50%);
}
.search-input input {
  width: 100%;
  height: 44px;
  padding: 9px 12px 9px 36px;
  border: 1px solid #dfe3e8;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #101a23;
  font-size: 14px;
  transition: all 0.2s ease;
}
.search-input input::placeholder {
  color: #a0a7ae;
}
.search-input input:focus {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}

.filter-control {
  width: 100%;
  height: 44px;
  padding: 9px 11px;
  border: 1px solid #dfe3e8;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #101a23;
  font-size: 14px;
  cursor: pointer;
}
.filter-control:focus {
  border-color: #177245;
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}

.filter-button,
.export-button {
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 9px 15px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.2s ease;
}

.filter-button {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.filter-button:hover {
  border-color: rgba(23, 114, 69, 0.05);
  background: rgba(23, 114, 69, 0.05);
}

.export-button {
  border: 1px solid #dfe3e8;
  background: #fff;
  color: #0D2B5A;
}
.export-button:hover {
  border-color: #177245;
  color: #177245;
}

/* =========================================================
   Logs Header
========================================================= */
.logs-card-header {
  border-bottom: 0;
}

/* =========================================================
   Table
========================================================= */
.table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.audit-table {
  width: 100%;
  min-width: 1050px;
  border-collapse: collapse;
}
.audit-table thead th {
  padding: 12px 18px;
  border-top: 1px solid #edf0f3;
  border-bottom: 1px solid #edf0f3;
  background: #fafbfc;
  color: #6e767e;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-align: left;
  white-space: nowrap;
}
.audit-table tbody tr {
  transition: background 0.2s ease;
}
.audit-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.025);
}
.audit-table tbody tr + tr {
  border-top: 1px solid #edf0f3;
}
.audit-table tbody td {
  padding: 14px 18px;
  color: #606870;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}

/* =========================================================
   User
========================================================= */
.user-info {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 170px;
}

.user-avatar {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.1);
  color: #177245;
  font-size: 12px;
  font-weight: 700;
}
.user-avatar.client {
  background: rgba(13, 202, 240, 0.1);
  color: #0899b8;
}

.user-info strong {
  display: block;
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
}
.user-info span {
  display: block;
  color: #8a9198;
  font-size: 14px;
  line-height: 1.3;
}

/* =========================================================
   Action Badge
========================================================= */
.action-badge,
.module-badge {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 4px 8px;
  border-radius: 5px;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  white-space: nowrap;
}

.action-badge.created {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}
.action-badge.updated {
  background: rgba(13, 202, 240, 0.09);
  color: #0796b3;
}
.action-badge.login {
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
}
.action-badge.payment {
  background: rgba(212, 175, 55, 0.13);
  color: #9a7900;
}

.module-badge {
  background: #f2f4f6;
  color: #68717a;
}

/* =========================================================
   Description / Date
========================================================= */
.description {
  display: block;
  min-width: 170px;
  color: #596169;
}

.audit-table td .date {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  white-space: nowrap;
}
.audit-table td small {
  display: block;
  margin-top: 2px;
  color: #8a9198;
  font-size: 14px;
  line-height: 1.3;
}

/* =========================================================
   View Log
========================================================= */
.view-log {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #e1e5e9;
  border-radius: 7px;
  color: #0D2B5A;
  text-decoration: none;
  transition: all 0.2s ease;
}
.view-log:hover {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}
.view-log i {
  font-size: 16px;
}

/* =========================================================
   Pagination
========================================================= */
.logs-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-top: 1px solid #edf0f3;
}

.pagination-info {
  color: #7d858d;
  font-size: 14px;
}

.pagination-buttons {
  display: flex;
  align-items: center;
  gap: 5px;
}
.pagination-buttons button {
  min-width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 7px;
  border: 1px solid #e1e5e9;
  border-radius: 6px;
  background: #fff;
  color: #68717a;
  font-size: 14px;
  cursor: pointer;
  transition: all 0.2s ease;
}
.pagination-buttons button:hover:not(:disabled), .pagination-buttons button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.pagination-buttons button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.pagination-buttons span {
  padding: 0 3px;
  color: #899198;
  font-size: 14px;
}

