  }
  .audit-summary {
    grid-template-columns: repeat(2, 1fr);
  }
  .audit-filter-grid {
    grid-template-columns: 1fr 1fr;
  }
  .search-field {
    grid-column: 1/-1;
  }
}
/* =========================================================
   XS
========================================================= */
@media (max-width: 767px) {
