    gap: 11px;
  }
}
/* =========================================================
   Audit Details Page
========================================================= */
.audit-details-page {
  width: 100%;
  margin: 0 auto;
  padding: 24px;
}
.audit-details-page * {
  box-sizing: border-box;
}
.audit-details-page a,
.audit-details-page button,
.audit-details-page input,
.audit-details-page select,
.audit-details-page textarea {
  font-family: inherit;
}

/* =========================================================
   Header
========================================================= */
.details-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 24px;
}

.details-header-left {
  min-width: 0;
}

.back-button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 15px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s ease;
}
.back-button i {
  font-size: 16px;
}
.back-button:hover {
  color: #177245;
}

.details-title {
  display: flex;
  align-items: center;
  gap: 13px;
}

.details-title-icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 20px;
}

.details-title h1 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.details-title p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/* =========================================================
   Layout
========================================================= */
.details-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 340px;
  align-items: start;
  gap: 20px;
}

.details-main,
.details-sidebar {
  min-width: 0;
}

/* =========================================================
   Card
========================================================= */
.details-card {
  margin-bottom: 20px;
  overflow: hidden;
  border: 1px solid #e8ebef;
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 4px 18px rgba(16, 26, 35, 0.04);
}
.details-card:last-child {
  margin-bottom: 0;
}

.details-card-header {
  padding: 20px 22px;
  border-bottom: 1px solid #edf0f3;
}
.details-card-header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.details-card-header p {
  margin: 0;
  color: #7b838b;
  font-size: 14px;
  line-height: 1.5;
}

.details-card-body {
  padding: 22px;
}
.details-card-body.no-padding {
