}

/* =========================================================
   Badges
========================================================= */
.action-badge,
.module-badge {
  display: inline-flex;
  align-items: center;
  min-height: 25px;
  padding: 4px 9px;
  border-radius: 5px;
  font-size: 14px;
  line-height: 1;
  font-weight: 600;
  white-space: nowrap;
}

.action-badge.updated {
  background: rgba(13, 202, 240, 0.09);
  color: #0796b3;
}
.action-badge.created {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}
.action-badge.deleted {
  background: rgba(220, 53, 69, 0.08);
  color: #dc3545;
}

.module-badge {
  background: #f2f4f6;
  color: #68717a;
}

/* =========================================================
   Info Grid
========================================================= */
.info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px 30px;
}

.info-item {
