  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 16px;
  border: 1px solid rgba(23, 114, 69, 0.12);
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.035);
}

.description-icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  font-size: 18px;
}

.description-box h3 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.description-box p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/* =========================================================
   Changes Table
========================================================= */
.changes-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.changes-table {
  width: 100%;
  min-width: 600px;
  border-collapse: collapse;
}
.changes-table thead th {
  padding: 12px 18px;
  border-bottom: 1px solid #edf0f3;
  background: #fafbfc;
  color: #6e767e;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-align: left;
}
.changes-table tbody tr + tr {
  border-top: 1px solid #edf0f3;
}
.changes-table tbody td {
  padding: 14px 18px;
  color: #626a72;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}
.changes-table tbody td:first-child {
  color: #0D2B5A;
  font-weight: 600;
}

.old-value {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 5px;
  background: rgba(220, 53, 69, 0.07);
  color: #dc3545;
}

.new-value {
  display: inline-block;
  padding: 4px 7px;
  border-radius: 5px;
  background: rgba(25, 135, 84, 0.08);
  color: #198754;
}

/* =========================================================
   Technical Information
========================================================= */
.technical-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.technical-item {
  padding: 14px;
  border: 1px solid #edf0f3;
  border-radius: 8px;
  background: #fafbfc;
}
.technical-item span {
  display: block;
  margin-bottom: 5px;
  color: #858d95;
  font-size: 14px;
  line-height: 1.4;
}
.technical-item strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.5;
  font-weight: 600;
  word-break: break-word;
}

/* =========================================================
   Performed User
========================================================= */
.performed-user {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-bottom: 18px;
  border-bottom: 1px solid #edf0f3;
}

.user-avatar {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(13, 202, 240, 0.1);
  color: #0796b3;
  font-size: 13px;
  font-weight: 700;
}

.performed-user strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.performed-user span {
  display: block;
  color: #858d95;
  font-size: 14px;
  line-height: 1.4;
  word-break: break-word;
}

/* =========================================================
   Sidebar Info
========================================================= */
.sidebar-info {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-top: 17px;
}
.sidebar-info > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.sidebar-info span {
  color: #858d95;
  font-size: 14px;
}
.sidebar-info strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}

/* =========================================================
   Related Resource
========================================================= */
.resource-box {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid #edf0f3;
  border-radius: 9px;
  background: #fafbfc;
}

