}

/* =========================================================
   XXL
========================================================= */
@media (min-width: 1400px) and (max-width: 1700px) {
  .details-layout {
    grid-template-columns: minmax(0, 1fr) 320px;
  }
}
/* =========================================================
   XL
========================================================= */
@media (min-width: 1200px) and (max-width: 1399px) {
  .details-layout {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
}
/* =========================================================
   LG
========================================================= */
@media (min-width: 992px) and (max-width: 1199px) {
  .audit-details-page {
    padding: 20px;
  }
  .details-layout {
    grid-template-columns: 1fr;
  }
  .details-sidebar {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 15px;
  }
  .details-sidebar .details-card {
    margin-bottom: 0;
  }
}
/* =========================================================
   MD
========================================================= */
@media (min-width: 768px) and (max-width: 991px) {
  .audit-details-page {
    padding: 18px;
  }
  .details-header {
    align-items: flex-start;
  }
  .details-sidebar {
    grid-template-columns: 1fr 1fr;
  }
  .details-sidebar .details-card:last-child {
    grid-column: 1/-1;
  }
}
/* =========================================================
   XS
========================================================= */
@media (max-width: 767px) {
  .audit-details-page {
    padding: 15px;
  }
  .details-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
    margin-bottom: 18px;
  }
  .details-title h1 {
    font-size: 20px;
  }
  .details-title p {
    font-size: 14px;
  }
  .details-title-icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
    font-size: 18px;
  }
  .details-card {
    margin-bottom: 15px;
    border-radius: 10px;
  }
  .details-card-header {
    padding: 16px;
  }
  .details-card-header h2 {
    font-size: 17px;
  }
  .details-card-header p {
    font-size: 14px;
  }
  .details-card-body {
    padding: 16px;
  }
  .info-grid,
  .technical-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .details-sidebar {
    grid-template-columns: 1fr;
  }
  .details-sidebar .details-card:last-child {
    grid-column: auto;
  }
  .description-box {
    padding: 13px;
  }
  .changes-table {
    min-width: 560px;
  }
  .sidebar-info > div {
    align-items: flex-start;
  }
}
