  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
}

/*================================*
* Table Wrapper
*=================================*/
.roles-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

/*================================*
* Roles Table
*=================================*/
.roles-table {
  width: 100%;
  min-width: 900px;
  border-collapse: collapse;
}
.roles-table th {
  padding: 14px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  background: rgba(16, 26, 35, 0.018);
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-align: left;
  white-space: nowrap;
}
.roles-table td {
  padding: 16px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
  vertical-align: middle;
}
.roles-table tbody tr {
  transition: background-color 0.2s ease;
}
.roles-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.018);
}
.roles-table tbody tr:last-child td {
  border-bottom: 0;
}

/*================================*
* Role Profile
*=================================*/
.role-profile {
  display: flex;
  align-items: center;
  gap: 11px;
}

.role-profile__icon {
  width: 38px;
  height: 38px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 38px;
}
.role-profile__icon i {
  font-size: 18px;
  line-height: 1;
}

.role-profile__info {
  min-width: 0;
}

.role-profile__name {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  text-decoration: none;
  transition: color 0.2s ease;
}
.role-profile__name:hover {
  color: #177245;
}

.role-profile__info > span {
  display: block;
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
  line-height: 1.3;
}

/*================================*
* Role Slug
*=================================*/
.role-slug {
  display: inline-flex;
  padding: 6px 9px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 5px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  font-family: monospace;
  font-size: 14px;
  line-height: 1.3;
}

/*================================*
* Role Count In Table
*=================================*/
.role-count {
  display: inline-flex;
  align-items: center;
  gap: 7px;
}

.role-count i {
  font-size: 16px;
  line-height: 1;
}

.role-count strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
}

.role-count small {
  color: #555555;
  font-size: 14px;
  line-height: 1;
}

.role-count--users i {
  color: #177245;
}

.role-count--permissions i {
  color: #198754;
}

/*================================*
* Role Date
*=================================*/
.role-date {
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* Actions
*=================================*/
.role-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.role-view-btn,
.role-edit-btn,
.role-delete-btn {
  width: 34px;
  height: 34px;
  margin: 0;
  padding: 0;
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  line-height: 1;
  text-decoration: none;
  cursor: pointer;
  transition: all 0.2s ease;
}
.role-view-btn i,
.role-edit-btn i,
.role-delete-btn i {
  display: block;
  font-size: 16px;
  line-height: 1;
}

/*================================*
* View
*=================================*/
.role-view-btn {
  border: 1px solid rgba(23, 114, 69, 0.15);
  background: rgba(23, 114, 69, 0.045);
  color: #177245;
}
.role-view-btn:hover {
  border-color: rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
}

/*================================*
* Edit
*=================================*/
.role-edit-btn {
  border: 1px solid rgba(13, 202, 240, 0.15);
  background: rgba(13, 202, 240, 0.045);
  color: #0dcaf0;
}
.role-edit-btn:hover {
  border-color: rgba(13, 202, 240, 0.25);
  background: rgba(13, 202, 240, 0.09);
  color: #0dcaf0;
}

/*================================*
* Delete
*=================================*/
.role-delete-btn {
  border: 1px solid rgba(220, 38, 38, 0.15);
  background: rgba(220, 38, 38, 0.045);
  color: #dc2626;
}
.role-delete-btn:hover {
  border-color: rgba(220, 38, 38, 0.25);
  background: rgba(220, 38, 38, 0.08);
  color: #dc2626;
}

.role-delete-btn--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.role-delete-btn--disabled:hover {
  border-color: rgba(220, 38, 38, 0.15);
  background: rgba(220, 38, 38, 0.045);
  color: #dc2626;
}

.role-delete-form {
  margin: 0;
  padding: 0;
  display: inline-flex;
}

/*================================*
* Table Footer
*=================================*/
.roles-table-card__footer {
  min-height: 62px;
  padding: 13px 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
@media (max-width: 767px) {
  .roles-table-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

/*================================*
* Pagination Info
*=================================*/
.roles-pagination-info {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.roles-pagination-info strong {
  color: #0D2B5A;
  font-weight: 600;
}

/*================================*
* Pagination
*=================================*/
.roles-pagination nav {
  display: flex;
}
.roles-pagination .pagination {
  margin: 0;
  display: flex;
  align-items: center;
  gap: 5px;
  list-style: none;
}
.roles-pagination .page-item .page-link {
  min-width: 34px;
  height: 34px;
  padding: 0 8px;
  border: 1px solid rgba(16, 26, 35, 0.08);
  border-radius: 6px;
  background: #fff;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 500;
  text-decoration: none;
  transition: all 0.2s ease;
}
.roles-pagination .page-item .page-link:hover {
  border-color: rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
}
.roles-pagination .page-item.active .page-link {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.roles-pagination .page-item.disabled .page-link {
  opacity: 0.4;
  cursor: not-allowed;
}

/*================================*
* Empty State
*=================================*/
.roles-empty {
  min-height: 330px;
  padding: 50px 25px;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}

.roles-empty__content {
  max-width: 420px;
  display: flex;
  align-items: center;
  flex-direction: column;
}

/*================================*
* Empty Icon
*=================================*/
.roles-empty__icon {
  width: 62px;
  height: 62px;
  margin-bottom: 16px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.roles-empty__icon i {
  font-size: 24px;
  line-height: 1;
}

/*================================*
* Empty Text
*=================================*/
.roles-empty__content h3 {
  margin: 0 0 8px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.roles-empty__content p {
  margin: 0 0 20px;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

