  font-size: 24px;
  font-weight: 700;
  line-height: 1.25;
}
.role-details-page__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Header Actions
*=================================*/
.role-details-page__actions {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-shrink: 0;
}
@media (min-width: 768px) and (max-width: 991px) {
  .role-details-page__actions {
    width: 100%;
  }
}
@media (max-width: 767px) {
  .role-details-page__actions {
    flex-direction: column;
  }
}

.role-details-secondary-btn,
.role-details-permissions-btn,
.role-details-primary-btn {
  min-height: 42px;
  padding: 0 16px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: border-color 0.2s ease, background-color 0.2s ease, color 0.2s ease;
}
.role-details-secondary-btn i,
.role-details-permissions-btn i,
.role-details-primary-btn i {
  font-size: 17px;
  line-height: 1;
}
@media (max-width: 767px) {
  .role-details-secondary-btn,
  .role-details-permissions-btn,
  .role-details-primary-btn {
    width: 100%;
  }
}

/*================================*
* Secondary Button
*=================================*/
.role-details-secondary-btn {
  border: 1px solid rgba(16, 26, 35, 0.1);
  background: #fff;
  color: #0D2B5A;
}
.role-details-secondary-btn:hover {
  border-color: rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}

/*================================*
* Manage Permissions Button
*=================================*/
.role-details-permissions-btn {
  border: 1px solid rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
}
.role-details-permissions-btn:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

/*================================*
* Primary Button
*=================================*/
.role-details-primary-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.role-details-primary-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}

/*================================*
* Overview
*=================================*/
.role-details-overview {
  margin-bottom: 20px;
  display: grid;
  /*
  |--------------------------------------------------------------------------
  | Fixed invalid minmax()
  |--------------------------------------------------------------------------
  */
  grid-template-columns: minmax(0, 2fr) repeat(2, minmax(0, 1fr));
  gap: 14px;
}
@media (min-width: 992px) and (max-width: 1199px) {
  .role-details-overview {
    grid-template-columns: 1fr 1fr;
  }
  .role-details-overview .role-details-card--identity {
    grid-column: 1/-1;
  }
}
@media (max-width: 767px) {
  .role-details-overview {
    grid-template-columns: 1fr;
  }
  .role-details-overview .role-details-card--identity {
    grid-column: auto;
  }
}

/*================================*
* Card
*=================================*/
.role-details-card {
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
  overflow: hidden;
}

/*================================*
* Identity Card
*=================================*/
.role-details-card--identity {
  min-height: 108px;
  padding: 20px;
}

.role-details-identity {
  min-height: 68px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.role-details-identity__icon {
  width: 54px;
  height: 54px;
  border-radius: 11px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 54px;
}
.role-details-identity__icon i {
  font-size: 25px;
  line-height: 1;
}

.role-details-identity__content > span {
  display: block;
  margin-bottom: 4px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.04em;
}
.role-details-identity__content h2 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.25;
}
.role-details-identity__content code {
  padding: 5px 8px;
  border: 1px solid rgba(16, 26, 35, 0.06);
  border-radius: 5px;
  background: rgba(16, 26, 35, 0.025);
  color: #555555;
  font-family: monospace;
  font-size: 14px;
}

/*================================*
* Statistic Card
*=================================*/
.role-details-stat {
  min-height: 108px;
  padding: 20px;
  display: flex;
  align-items: center;
  gap: 13px;
}

.role-details-stat__icon {
  width: 44px;
  height: 44px;
  border-radius: 9px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 44px;
}
.role-details-stat__icon i {
  font-size: 21px;
  line-height: 1;
}

.role-details-stat__icon--users {
  background: rgba(13, 202, 240, 0.09);
  color: #0dcaf0;
}

.role-details-stat__icon--permissions {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}

.role-details-stat__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.role-details-stat__content span {
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
}

.role-details-stat__content strong {
  margin-bottom: 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 22px;
  font-weight: 600;
  line-height: 1.2;
}

.role-details-stat__content small {
  color: rgba(85, 85, 85, 0.1);
  font-size: 14px;
  line-height: 1.4;
}

/*================================*
* Main Grid
*=================================*/
.role-details-grid {
  margin-bottom: 20px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 14px;
}
@media (min-width: 992px) and (max-width: 1199px) {
  .role-details-grid {
    grid-template-columns: 1fr;
  }
}

/*================================*
* Card Header
*=================================*/
.role-details-card__header {
  min-height: 76px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.role-details-card__header h2 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.role-details-card__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*================================*
* Count Badge
*=================================*/
.role-details-count {
  min-width: 34px;
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(16, 26, 35, 0.07);
