  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*================================*
* Role Information
*=================================*/
.role-details-information {
  padding: 6px 20px 20px;
}

.role-details-information__item {
  min-height: 62px;
  padding: 14px 0;
