  }
}

.role-details-permissions-footer__info {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.role-details-permissions-footer__info i {
  color: #177245;
  font-size: 16px;
}

.role-details-manage-permissions-btn {
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid #177245;
  border-radius: 7px;
  background: #177245;
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: background-color 0.2s ease, border-color 0.2s ease;
}
.role-details-manage-permissions-btn i {
  font-size: 16px;
}
.role-details-manage-permissions-btn:hover {
  border-color: rgba(23, 114, 69, 0.7);
  background: rgba(23, 114, 69, 0.7);
  color: #fff;
}
@media (max-width: 767px) {
  .role-details-manage-permissions-btn {
    width: 100%;
  }
}

/*================================*
* Assigned Users Card
*=================================*/
.role-details-card--users {
  margin-bottom: 20px;
}

/*================================*
* Users Table
*=================================*/
.role-users-table-wrapper {
  width: 100%;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.role-users-table {
  width: 100%;
  min-width: 760px;
  border-collapse: collapse;
}
.role-users-table th {
  padding: 14px 20px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  background: rgba(16, 26, 35, 0.018);
