}

.permission-empty h3 {
  margin: 0 0 7px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.permission-empty p {
  max-width: 430px;
  margin: 0 0 20px;
