/*================================*
* Permission Create Page
*=================================*/
.permission-create-page {
  width: 100%;
}

/*================================*
* Page Header
*=================================*/
.permission-create-page__header {
  margin-bottom: 24px;
}

.permission-create-page__header-content {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
}
@media (min-width: 768px) and (max-width: 991px) {
  .permission-create-page__header-content {
    align-items: flex-start;
    flex-direction: column;
    gap: 18px;
  }
}

.permission-create-page__heading .permission-create-page__eyebrow {
  display: inline-block;
  margin-bottom: 7px;
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}
.permission-create-page__heading h1 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.25;
}
.permission-create-page__heading p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Header Action
*=================================*/
.permission-create-page__actions {
  flex-shrink: 0;
}
@media (min-width: 768px) and (max-width: 991px) {
  .permission-create-page__actions {
    width: 100%;
  }
}

.permission-secondary-btn {
  min-height: 42px;
  padding: 0 16px;
  border: 1px solid rgba(16, 26, 35, 0.1);
  border-radius: 7px;
  background: #fff;
  color: #0D2B5A;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  text-decoration: none;
  transition: all 0.2s ease;
}
.permission-secondary-btn i {
  font-size: 17px;
  line-height: 1;
}
.permission-secondary-btn:hover {
  border-color: rgba(23, 114, 69, 0.25);
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}
@media (min-width: 768px) and (max-width: 991px) {
  .permission-secondary-btn {
    width: 100%;
  }
}

/*================================*
* Create Card
*=================================*/
.permission-create-card {
  width: 100%;
  max-width: 760px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 12px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.035);
}

/*================================*
* Card Header
*=================================*/
.permission-create-card__header {
  padding: 22px 24px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  gap: 13px;
}

.permission-create-card__icon {
  width: 44px;
  height: 44px;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 44px;
}
.permission-create-card__icon i {
  font-size: 21px;
  line-height: 1;
}

.permission-create-card__header h2 {
  margin: 0 0 4px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.3;
}
.permission-create-card__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*================================*
* Form
*=================================*/
.permission-create-form {
  padding: 24px;
}

/*================================*
* Form Group
*=================================*/
.permission-create-form__group {
  margin-bottom: 22px;
}

.permission-create-form__group > label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
}
.permission-create-form__group > label span {
  color: #dc2626;
}

/*================================*
* Text Input
*=================================*/
.permission-create-form__input {
  position: relative;
}
.permission-create-form__input i {
  position: absolute;
  top: 50%;
  left: 14px;
  color: rgba(85, 85, 85, 0.05);
  font-size: 18px;
  line-height: 1;
  transform: translateY(-50%);
  pointer-events: none;
}
.permission-create-form__input input {
  width: 100%;
  height: 46px;
  padding: 0 14px 0 43px;
  border: 1px solid rgba(16, 26, 35, 0.1);
  border-radius: 7px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.4;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.permission-create-form__input input::placeholder {
  color: rgba(85, 85, 85, 0.2);
}
.permission-create-form__input input:focus {
  border-color: rgba(23, 114, 69, 0.45);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}

/*================================*
* Textarea
*=================================*/
.permission-create-form__textarea {
  position: relative;
}
.permission-create-form__textarea i {
  position: absolute;
  top: 15px;
  left: 14px;
  color: rgba(85, 85, 85, 0.05);
  font-size: 18px;
  line-height: 1;
  pointer-events: none;
}
.permission-create-form__textarea textarea {
  width: 100%;
  min-height: 130px;
  padding: 13px 14px 13px 43px;
  border: 1px solid rgba(16, 26, 35, 0.1);
  border-radius: 7px;
  outline: none;
  resize: vertical;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  line-height: 1.6;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.permission-create-form__textarea textarea::placeholder {
  color: rgba(85, 85, 85, 0.2);
}
.permission-create-form__textarea textarea:focus {
  border-color: rgba(23, 114, 69, 0.45);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.08);
}

/*================================*
* Help Text
*=================================*/
.permission-create-form__help {
  margin: 8px 0 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*================================*
* Information Box
*=================================*/
.permission-create-info {
  margin-bottom: 24px;
  padding: 16px;
  border: 1px solid rgba(13, 202, 240, 0.14);
  border-radius: 8px;
  background: rgba(13, 202, 240, 0.045);
  display: flex;
  align-items: flex-start;
  gap: 11px;
}

.permission-create-info__icon {
  width: 34px;
  height: 34px;
  border-radius: 7px;
  background: rgba(13, 202, 240, 0.1);
  color: #0dcaf0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 34px;
}
.permission-create-info__icon i {
  font-size: 17px;
  line-height: 1;
}

.permission-create-info__content h3 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}
.permission-create-info__content p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*================================*
* Form Footer
*=================================*/
.permission-create-form__footer {
  padding-top: 20px;
  border-top: 1px solid rgba(16, 26, 35, 0.07);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
}
@media (max-width: 767px) {
  .permission-create-form__footer {
    flex-direction: column-reverse;
  }
}

/*================================*
* Buttons
*=================================*/
.permission-cancel-btn,
.permission-submit-btn {
  min-height: 42px;
  padding: 0 17px;
  border-radius: 7px;
