}
.smart-buy-outline-btn i {
  font-size: 14px;
}
.smart-buy-outline-btn:hover {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}

/*==================================================
| Statistics
==================================================*/
.smart-buy-stats {
  margin-bottom: 15px;
