}

.smart-buy-stat-card__icon--purple {
  background: #f1edff;
  color: #7255b7;
}

.smart-buy-stat-card__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-stat-card__content span {
