  transition: color 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}
.smart-buy-action-btn i {
  font-size: 14px;
}
.smart-buy-action-btn:hover {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
}

/*==================================================
| Pagination
==================================================*/
.smart-buy-pagination {
  min-height: 56px;
  padding: 9px 13px;
  border-top: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.smart-buy-pagination__info {
  color: rgba(85, 85, 85, 0.8);
  font-size: 14px;
}

.smart-buy-pagination__info strong {
  color: #0D2B5A;
  font-weight: 600;
}

.smart-buy-pagination__links {
  display: flex;
  align-items: center;
  gap: 3px;
}

.smart-buy-pagination__btn {
  min-width: 31px;
  height: 31px;
  padding: 0 8px;
  border: 1px solid rgba(16, 26, 35, 0.08);
  border-radius: 6px;
  background: #fff;
  color: #555555;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: color 0.2s ease, border-color 0.2s ease, background-color 0.2s ease;
}
.smart-buy-pagination__btn i {
  font-size: 14px;
}
.smart-buy-pagination__btn:hover {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}

.smart-buy-pagination__btn--active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.smart-buy-pagination__btn--active:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

.smart-buy-pagination__btn--disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.smart-buy-pagination__btn--disabled:hover {
  border-color: rgba(16, 26, 35, 0.08);
  background: #fff;
  color: #555555;
}

.smart-buy-pagination__dots {
  padding: 0 3px;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

/*==================================================
| Responsive - LG
==================================================*/
@media (min-width: 992px) and (max-width: 1199px) {
  .smart-buy-stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/*==================================================
| Responsive - MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .smart-buy-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .smart-buy-card__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .smart-buy-card__header-actions {
    width: 100%;
  }
  .smart-buy-search {
    flex: 1;
    width: auto;
  }
  .smart-buy-filters {
    flex-wrap: wrap;
  }
  .smart-buy-filter-field {
    flex: 1;
    min-width: 140px;
  }
  .smart-buy-clear-filter {
    margin-left: 0;
  }
}
/*==================================================
| Responsive - XS
==================================================*/
@media (max-width: 767px) {
  .smart-buy-page__header h1 {
    font-size: 20px;
  }
  .smart-buy-page__header-actions {
    width: 100%;
  }
  .smart-buy-outline-btn {
    width: 100%;
  }
  .smart-buy-stats {
    grid-template-columns: 1fr;
    gap: 8px;
  }
  .smart-buy-card__header {
    padding: 12px 13px;
  }
  .smart-buy-card__header-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .smart-buy-search {
    width: 100%;
  }
  .smart-buy-filter-btn {
    width: 100%;
  }
  .smart-buy-filters {
    align-items: stretch;
    flex-direction: column;
    padding: 11px 13px;
  }
  .smart-buy-filter-field {
    width: 100%;
  }
  .smart-buy-clear-filter {
    width: 100%;
    margin: 0;
    text-align: left;
  }
  .smart-buy-pagination {
    align-items: flex-start;
    flex-direction: column;
  }
  .smart-buy-pagination__links {
    width: 100%;
    justify-content: flex-end;
  }
}
/*==================================================
| Smart Buy Details Page
==================================================*/
.smart-buy-details-page {
  width: 100%;
}

/*==================================================
| Header
==================================================*/
.smart-buy-details-header {
  margin-bottom: 16px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
}

.smart-buy-details-header__left {
  min-width: 0;
}

.smart-buy-details-back {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  margin-bottom: 9px;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s ease;
}
.smart-buy-details-back i {
  font-size: 14px;
}
.smart-buy-details-back:hover {
  color: #177245;
}

.smart-buy-details-title {
  display: flex;
  align-items: center;
  gap: 11px;
}

.smart-buy-details-title__icon {
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-details-title__icon i {
  font-size: 20px;
}

.smart-buy-details-eyebrow {
  display: block;
  margin-bottom: 2px;
  color: #177245;
  font-size: 14px;
  font-weight: 700;
  line-height: 1.3;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.smart-buy-details-title h1 {
  margin: 0 0 2px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
}

.smart-buy-details-title p {
  margin: 0;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  line-height: 1.3;
}

.smart-buy-details-header__actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

/*==================================================
| Status
==================================================*/
.smart-buy-details-status {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 25px;
  padding: 4px 8px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.smart-buy-details-status > i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.smart-buy-details-status--pending {
  background: #fff4dc;
  color: #ad7711;
}

/*==================================================
| Header Buttons
==================================================*/
.smart-buy-details-outline-btn,
.smart-buy-details-primary-btn {
  min-height: 38px;
  padding: 0 11px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  white-space: nowrap;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.smart-buy-details-outline-btn {
  border: 1px solid rgba(16, 26, 35, 0.09);
  background: #fff;
  color: #555555;
}
.smart-buy-details-outline-btn:hover {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}

.smart-buy-details-primary-btn {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.smart-buy-details-primary-btn:hover {
  border-color: rgba(23, 114, 69, 0.07);
  background: rgba(23, 114, 69, 0.07);
  color: #fff;
  box-shadow: 0 5px 14px rgba(23, 114, 69, 0.12);
}

.smart-buy-details-outline-btn i,
.smart-buy-details-primary-btn i {
  font-size: 14px;
}

/*==================================================
| Progress Card
==================================================*/
.smart-buy-details-progress-card {
  margin-bottom: 15px;
  padding: 14px 16px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

.smart-buy-details-progress-header {
  margin-bottom: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}

.smart-buy-details-progress-header > div {
  display: flex;
  align-items: center;
  gap: 7px;
}

.smart-buy-details-progress-header span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-details-progress-header strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-details-progress-header > span {
  color: #177245;
  font-weight: 600;
}

/*==================================================
| Progress
==================================================*/
.smart-buy-details-progress {
  position: relative;
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 5px;
}

.smart-buy-details-progress__line {
  position: absolute;
  top: 15px;
  left: 8%;
  width: 84%;
  height: 2px;
  background: #e5e8ea;
}

.smart-buy-details-progress__line > span {
  display: block;
  height: 100%;
  background: #177245;
}

.smart-buy-details-progress-step {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 5px;
  color: rgba(85, 85, 85, 0.2);
  text-align: center;
}

.smart-buy-details-progress-step > span {
  width: 31px;
  height: 31px;
  border: 2px solid #dfe3e5;
  border-radius: 50%;
  background: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-details-progress-step > span i {
  font-size: 13px;
}

.smart-buy-details-progress-step strong {
  color: inherit;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
}

.smart-buy-details-progress-step--active {
  color: #177245;
}

.smart-buy-details-progress-step--active > span {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}

/*==================================================
| Main Layout
==================================================*/
.smart-buy-details-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  align-items: start;
  gap: 15px;
}

.smart-buy-details-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.smart-buy-details-sidebar {
  min-width: 0;
  position: sticky;
  top: 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

/*==================================================
| Card
==================================================*/
.smart-buy-details-card {
  overflow: hidden;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

.smart-buy-details-card__header {
  min-height: 57px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.06);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.smart-buy-details-card__header h2 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
}

.smart-buy-details-card__header p {
  margin: 0;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  line-height: 1.4;
}

/*==================================================
| Product Details
==================================================*/
.smart-buy-product-details {
  padding: 17px;
  display: flex;
  align-items: flex-start;
  gap: 13px;
}

.smart-buy-product-details__image {
  width: 68px;
  height: 68px;
  flex: 0 0 68px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 9px;
  background: #f8f9fa;
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-product-details__image i {
  font-size: 27px;
}

.smart-buy-product-details__content {
  min-width: 0;
  flex: 1;
}

.smart-buy-product-details__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-product-details__top span:first-child {
  display: block;
  margin-bottom: 2px;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-product-details__top h3 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.3;
}

.smart-buy-product-tag {
  padding: 4px 8px;
  border-radius: 20px;
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.smart-buy-product-details__content > p {
  margin: 9px 0 13px;
  color: #555555;
  font-size: 14px;
  line-height: 1.55;
}

.smart-buy-product-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.smart-buy-product-meta > div {
  padding: 9px 10px;
  border: 1px solid rgba(16, 26, 35, 0.055);
  border-radius: 7px;
  background: #fafbfc;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.smart-buy-product-meta span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-product-meta strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*==================================================
| Delivery Grid
==================================================*/
.smart-buy-delivery-grid {
  padding: 8px 16px 14px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
}

.smart-buy-info-item {
  min-width: 0;
  padding: 10px 11px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
}

.smart-buy-info-item:nth-last-child(-n+2) {
  border-bottom: 0;
}

.smart-buy-info-item--full {
  grid-column: 1/-1;
}

.smart-buy-info-item span {
  display: block;
  margin-bottom: 3px;
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  line-height: 1.3;
}

.smart-buy-info-item strong {
  display: block;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*==================================================
| Customer Note
==================================================*/
.smart-buy-customer-note {
  padding: 15px 17px;
  display: flex;
  align-items: flex-start;
  gap: 9px;
  background: rgba(23, 114, 69, 0.025);
}

.smart-buy-customer-note > i {
  color: #177245;
  font-size: 18px;
  flex: 0 0 auto;
}

.smart-buy-customer-note p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.55;
}

/*==================================================
| Timeline
==================================================*/
.smart-buy-details-timeline {
  padding: 17px 18px 8px;
}

.smart-buy-details-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 10px;
  padding-bottom: 22px;
}

.smart-buy-details-timeline-item:last-child {
  padding-bottom: 6px;
}

.smart-buy-details-timeline-item:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 34px;
  left: 16px;
  width: 1px;
  height: calc(100% - 22px);
  background: #e2e5e7;
}

.smart-buy-details-timeline-item__indicator {
  position: relative;
  z-index: 1;
}

.smart-buy-details-timeline-item__indicator > span {
  width: 33px;
  height: 33px;
  border: 1px solid #dfe3e5;
  border-radius: 50%;
  background: #fff;
  color: rgba(85, 85, 85, 0.8);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-details-timeline-item__indicator > span i {
  font-size: 14px;
}

.smart-buy-details-timeline-item--active .smart-buy-details-timeline-item__indicator > span {
  border-color: rgba(23, 114, 69, 0.2);
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}

.smart-buy-details-timeline-item--future {
  opacity: 0.55;
}

.smart-buy-details-timeline-item__content {
  min-width: 0;
  padding-top: 2px;
}

.smart-buy-details-timeline-item__content > div {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-details-timeline-item__content h3 {
  margin: 0 0 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.35;
}

.smart-buy-details-timeline-item__content time,
.smart-buy-details-timeline-item__content > div > span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  line-height: 1.3;
  white-space: nowrap;
}

.smart-buy-details-timeline-item__content p {
  margin: 5px 0 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.45;
}

/*==================================================
| Customer Profile
==================================================*/
.smart-buy-customer-profile {
  padding: 14px 15px;
  display: flex;
  align-items: center;
  gap: 9px;
}

.smart-buy-customer-profile__avatar {
  width: 41px;
  height: 41px;
  flex: 0 0 41px;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 14px;
  font-weight: 700;
}

.smart-buy-customer-profile > div:last-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-customer-profile strong {
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.smart-buy-customer-profile span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

/*==================================================
| Customer Contact
==================================================*/
.smart-buy-customer-contact {
  padding: 0 15px 13px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.smart-buy-customer-contact > div {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
}

.smart-buy-customer-contact i {
  color: #177245;
  font-size: 14px;
}

.smart-buy-customer-contact span {
  overflow: hidden;
  color: #555555;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*==================================================
| Summary
==================================================*/
.smart-buy-summary {
  padding: 4px 15px 8px;
}

.smart-buy-summary > div {
  min-height: 42px;
  padding: 7px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-summary > div:last-child {
  border-bottom: 0;
}

.smart-buy-summary span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-summary strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}

.smart-buy-summary__total {
  margin-top: 3px;
  padding-top: 10px !important;
  border-top: 1px solid rgba(16, 26, 35, 0.08);
}

.smart-buy-summary__total span {
  color: #0D2B5A;
  font-weight: 600;
}

.smart-buy-summary__total strong {
  color: #177245;
  font-size: 18px;
  font-weight: 700;
}

/*==================================================
| Quick Actions
==================================================*/
.smart-buy-quick-actions {
  padding: 4px 8px 8px;
}

.smart-buy-quick-action {
  width: 100%;
  min-height: 44px;
  padding: 6px 7px;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  color: #555555;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: color 0.2s ease;
}

.smart-buy-quick-action:last-child {
  border-bottom: 0;
}

.smart-buy-quick-action > span:nth-child(2) {
  flex: 1;
}

.smart-buy-quick-action > i {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-quick-action:hover {
  color: #177245;
}

.smart-buy-quick-action__icon {
  width: 30px;
  height: 30px;
  flex: 0 0 30px;
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-quick-action__icon i {
  font-size: 14px;
}

/*==================================================
| Notice
==================================================*/
.smart-buy-details-notice {
  padding: 12px;
  border: 1px solid #e9dfc7;
  border-radius: 9px;
  background: #fffaf0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.smart-buy-details-notice__icon {
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  border-radius: 7px;
  background: #fff0c9;
  color: #a67516;
  display: inline-flex;
  align-items: center;
