  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-quote-field-footer span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
  line-height: 1.3;
}

.smart-buy-quote-field-footer span:last-child {
  color: rgba(85, 85, 85, 0.8);
  white-space: nowrap;
}

/*==================================================
| Checkbox
==================================================*/
.smart-buy-quote-checkbox {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: #555555;
  font-size: 14px;
  cursor: pointer;
}

.smart-buy-quote-checkbox input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.smart-buy-quote-checkbox__box {
  width: 17px;
  height: 17px;
  border: 1px solid #cfd4d7;
  border-radius: 4px;
  background: #fff;
  display: inline-flex;
  flex: 0 0 17px;
  transition: border-color 0.2s ease, background-color 0.2s ease;
}

.smart-buy-quote-checkbox input:checked ~ .smart-buy-quote-checkbox__box {
  border-color: #177245;
  background: #177245;
}

.smart-buy-quote-checkbox input:checked ~ .smart-buy-quote-checkbox__box::after {
  content: "";
  width: 7px;
  height: 4px;
  margin: 4px 0 0 4px;
  border-left: 2px solid #fff;
  border-bottom: 2px solid #fff;
  transform: rotate(-45deg);
}

/*==================================================
| Summary
==================================================*/
.smart-buy-quote-summary {
  padding: 5px 15px 8px;
}

.smart-buy-quote-summary > div {
  min-height: 40px;
  padding: 6px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-quote-summary > div:last-child {
  border-bottom: 0;
}

.smart-buy-quote-summary span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-quote-summary strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.smart-buy-quote-summary__subtotal {
  margin-top: 2px;
  border-top: 1px solid rgba(16, 26, 35, 0.08);
}

.smart-buy-quote-summary__subtotal span {
  color: #0D2B5A;
  font-weight: 600;
}

.smart-buy-quote-summary__discount {
  color: #2b8750 !important;
}

.smart-buy-quote-summary__total {
  margin-top: 3px;
  min-height: 52px !important;
  border-top: 1px solid rgba(16, 26, 35, 0.08);
  border-bottom: 0 !important;
}

.smart-buy-quote-summary__total span {
  color: #0D2B5A;
  font-weight: 700;
}

.smart-buy-quote-summary__total strong {
  color: #177245;
  font-size: 20px;
  font-weight: 700;
}

/*==================================================
| Customer Pay
==================================================*/
.smart-buy-quote-customer-pay {
  margin: 5px 12px 12px;
  padding: 11px;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.06);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-quote-customer-pay span {
  color: #555555;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-quote-customer-pay strong {
  color: #177245;
  font-size: 18px;
  font-weight: 700;
}

/*==================================================
| Info
==================================================*/
.smart-buy-quote-info {
  padding: 5px 15px 9px;
}

.smart-buy-quote-info > div {
  min-height: 42px;
  padding: 7px 0;
  border-bottom: 1px solid rgba(16, 26, 35, 0.055);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.smart-buy-quote-info > div:last-child {
  border-bottom: 0;
}

.smart-buy-quote-info span {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-quote-info strong {
  max-width: 160px;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*==================================================
| Notice
==================================================*/
.smart-buy-quote-notice {
  padding: 12px;
  border: 1px solid #e9dfc7;
  border-radius: 9px;
  background: #fffaf0;
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

.smart-buy-quote-notice__icon {
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  border-radius: 7px;
  background: #fff0c9;
  color: #a67516;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.smart-buy-quote-notice__icon i {
  font-size: 14px;
}

.smart-buy-quote-notice strong {
  display: block;
  margin-bottom: 3px;
  color: #765615;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-quote-notice p {
  margin: 0;
  color: #876f42;
  font-size: 14px;
  line-height: 1.45;
}

/*==================================================
| Footer
==================================================*/
.smart-buy-quote-footer {
  margin-top: 15px;
  padding: 12px 15px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

.smart-buy-quote-footer > div:first-child {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.smart-buy-quote-footer > div:first-child span {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.smart-buy-quote-footer > div:first-child small {
  color: rgba(85, 85, 85, 0.2);
  font-size: 14px;
}

.smart-buy-quote-footer__actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

/*==================================================
| Footer Buttons
==================================================*/
.smart-buy-quote-cancel,
.smart-buy-quote-draft,
.smart-buy-quote-send {
  min-height: 38px;
  padding: 0 12px;
  border-radius: 7px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: color 0.2s ease, background-color 0.2s ease, border-color 0.2s ease, opacity 0.2s ease;
}

.smart-buy-quote-cancel {
  color: #555555;
}
.smart-buy-quote-cancel:hover {
  background: #f7f8f9;
  color: #0D2B5A;
}

.smart-buy-quote-draft {
  border: 1px solid rgba(16, 26, 35, 0.09);
  background: #fff;
  color: #555555;
}
.smart-buy-quote-draft:hover {
  border-color: rgba(16, 26, 35, 0.15);
  background: #f8f9fa;
}

.smart-buy-quote-send {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.smart-buy-quote-send:hover {
  border-color: rgba(23, 114, 69, 0.07);
  background: rgba(23, 114, 69, 0.07);
  color: #fff;
}

.smart-buy-quote-draft:disabled,
.smart-buy-quote-send:disabled {
  opacity: 0.65;
  cursor: wait;
}

/*==================================================
| Loading
==================================================*/
.smart-buy-quote-spin {
  animation: smartBuyQuoteSpin 0.8s linear infinite;
}

@keyframes smartBuyQuoteSpin {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}
/*==================================================
| Responsive - LG
==================================================*/
@media (min-width: 992px) and (max-width: 1199px) {
  .smart-buy-quote-layout {
    grid-template-columns: minmax(0, 1fr) 270px;
  }
}
/*==================================================
| Responsive - MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .smart-buy-quote-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .smart-buy-quote-layout {
    grid-template-columns: 1fr;
  }
  .smart-buy-quote-sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .smart-buy-quote-notice {
    grid-column: 1/-1;
  }
}
/*==================================================
| Responsive - XS
==================================================*/
@media (max-width: 767px) {
  .smart-buy-quote-heading h1 {
    font-size: 20px;
  }
  .smart-buy-quote-heading__icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
  }
  .smart-buy-quote-request {
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .smart-buy-quote-grid--two {
    grid-template-columns: 1fr;
  }
  .smart-buy-quote-card__body {
    padding: 13px;
  }
  .smart-buy-quote-charge-row {
    align-items: flex-start;
    flex-direction: column;
  }
  .smart-buy-quote-charge-input {
    width: 100%;
    flex-basis: auto;
  }
  .smart-buy-quote-sidebar {
    grid-template-columns: 1fr;
  }
  .smart-buy-quote-notice {
    grid-column: auto;
  }
  .smart-buy-quote-footer {
    align-items: stretch;
    flex-direction: column;
  }
  .smart-buy-quote-footer__actions {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .smart-buy-quote-cancel,
  .smart-buy-quote-draft,
  .smart-buy-quote-send {
    width: 100%;
    padding: 0 7px;
  }
}
