  margin-top: 15px;
  padding: 12px 15px;
  border: 1px solid rgba(16, 26, 35, 0.07);
  border-radius: 10px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  box-shadow: 0 3px 14px rgba(16, 26, 35, 0.025);
}

