/*==================================================
| Responsive LG
==================================================*/
@media (min-width: 992px) and (max-width: 1199px) {
  .my-smart-buy-details-layout {
    grid-template-columns: minmax(0, 1fr) 270px;
  }
}
/*==================================================
| Responsive MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .my-smart-buy-details-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .my-smart-buy-details-layout {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-details-sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .my-smart-buy-details-help {
    grid-column: 1/-1;
  }
  .my-smart-buy-details-progress {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 18px;
  }
  .my-smart-buy-details-progress__step:nth-child(3)::after {
    display: none;
  }
}
/*==================================================
| Responsive XS
==================================================*/
@media (max-width: 767px) {
  .my-smart-buy-details-heading h1 {
    font-size: 20px;
  }
  .my-smart-buy-details-heading__icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
  }
  .my-smart-buy-details-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }
  .my-smart-buy-details-summary__item {
    padding: 5px 8px;
    border-right: 0;
  }
  .my-smart-buy-details-summary__item:first-child {
    padding-left: 8px;
  }
  .my-smart-buy-details-summary__item:last-child {
    padding-right: 8px;
  }
  .my-smart-buy-details-layout {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-details-sidebar {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-details-help {
    grid-column: auto;
  }
  .my-smart-buy-details-progress {
    grid-template-columns: 1fr;
    gap: 0;
  }
  .my-smart-buy-details-progress__step {
    min-height: 65px;
    padding-left: 42px;
    padding-right: 0;
    text-align: left;
  }
  .my-smart-buy-details-progress__step:not(:last-child)::after {
    top: 29px;
    left: 14px;
    width: 1px;
    height: calc(100% - 1px);
  }
  .my-smart-buy-details-progress__icon {
    position: absolute;
    top: 0;
    left: 0;
    margin: 0;
  }
  .my-smart-buy-details-progress__step > div:last-child {
    padding-top: 2px;
  }
  .my-smart-buy-details-product {
    flex-direction: column;
  }
  .my-smart-buy-details-shipment__tracking {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .my-smart-buy-details-copy {
    margin-left: 0;
  }
  .my-smart-buy-details-shipment__grid {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-details-payment {
    align-items: flex-start;
    flex-wrap: wrap;
  }
  .my-smart-buy-details-payment__amount {
    width: 100%;
    padding-top: 8px;
    border-top: 1px solid rgba(16, 26, 35, 0.055);
    align-items: flex-start;
  }
}
