/*==================================================
| Responsive MD
==================================================*/
@media (min-width: 768px) and (max-width: 991px) {
  .my-smart-buy-quote-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .my-smart-buy-quote-layout {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-quote-sidebar {
    position: static;
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .my-smart-buy-quote-help {
    grid-column: 1/-1;
  }
  .my-smart-buy-quote-request {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/*==================================================
