==================================================*/
@media (max-width: 767px) {
  .my-smart-buy-quote-heading h1 {
    font-size: 20px;
  }
  .my-smart-buy-quote-heading__icon {
    width: 40px;
    height: 40px;
    flex-basis: 40px;
  }
  .my-smart-buy-quote-layout {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-quote-sidebar {
    grid-template-columns: 1fr;
  }
  .my-smart-buy-quote-help {
