  letter-spacing: 1px;
}
.customer-product-card__rating small {
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Product Bottom
|--------------------------------------------------------------------------
*/
.customer-product-card__bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.customer-product-card__price {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 5px;
}
.customer-product-card__price del {
  color: #aaa;
  font-size: 14px;
}
.customer-product-card__price strong {
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.3;
  font-weight: 700;
}

/*
|--------------------------------------------------------------------------
| Add To Cart
|--------------------------------------------------------------------------
*/
.customer-product-card__cart {
  width: 36px;
  height: 36px;
