  align-items: center;
  justify-content: center;
  border: 1px solid rgba(23, 114, 69, 0.2);
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
  font-size: 17px;
  cursor: pointer;
  transition: 0.2s;
}
.customer-product-card__cart:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
  transform: translateY(-1px);
}

/*
|--------------------------------------------------------------------------
| Pagination
|--------------------------------------------------------------------------
*/
.customer-shop-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin-top: 28px;
}
.customer-shop-pagination button {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}
.customer-shop-pagination button:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.customer-shop-pagination button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.customer-shop-pagination button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.customer-shop-pagination > span {
  padding: 0 3px;
  color: #999;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .customer-shop-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
/*
|--------------------------------------------------------------------------
| LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .customer-shop-layout {
    grid-template-columns: 220px minmax(0, 1fr);
  }
  .customer-shop-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .customer-shop-hero__stats {
    display: none;
  }
  .customer-shop-search {
    width: 190px;
  }
}
/*
|--------------------------------------------------------------------------
| MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .customer-shop-hero {
    min-height: auto;
    padding: 25px;
  }
  .customer-shop-layout {
    grid-template-columns: 1fr;
  }
  .customer-shop-sidebar {
    position: static;
  }
  .customer-shop-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .customer-shop-toolbar {
    align-items: flex-start;
    flex-direction: column;
  }
  .customer-shop-toolbar__right {
    width: 100%;
  }
  .customer-shop-search {
    flex: 1;
    width: auto;
  }
}
/*
|--------------------------------------------------------------------------
| XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .customer-shop-hero {
    padding: 20px;
  }
  .customer-shop-hero h1 {
    font-size: 24px;
  }
  .customer-shop-topbar {
    margin-bottom: 15px;
  }
  .customer-shop-layout {
    gap: 15px;
  }
  .customer-shop-sidebar {
    padding: 14px;
  }
  .customer-shop-toolbar__right {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 7px;
  }
  .customer-shop-search {
    grid-column: 1/-1;
    width: 100%;
  }
  .customer-shop-sort-wrap {
    width: 100%;
  }
  .customer-shop-view {
    width: 100%;
    justify-content: center;
  }
  .customer-shop-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 9px;
  }
  .customer-product-card__content {
    padding: 10px;
  }
  .customer-product-card__category {
    font-size: 14px;
  }
  .customer-product-card__content h2 {
    min-height: 38px;
  }
  .customer-product-card__price {
    display: block;
  }
  .customer-product-card__price del,
  .customer-product-card__price strong {
    display: block;
  }
  .customer-product-card__cart {
    width: 32px;
    height: 32px;
    flex-basis: 32px;
    font-size: 16px;
  }
  .customer-product-card__quick {
    display: none;
  }
}
