.products-summary strong {
  display: block;
  color: #0D2B5A;
  font-size: 20px;
  line-height: 1.3;
  font-weight: 700;
}

/*
|--------------------------------------------------------------------------
| Products Card
|--------------------------------------------------------------------------
*/
.products-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}
.products-card__filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.products-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px 20px;
  border-top: 1px solid rgba(221, 221, 221, 0.7);
}
.products-card__footer > span {
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Search
|--------------------------------------------------------------------------
*/
.products-search {
  position: relative;
  width: 300px;
}
.products-search i {
  position: absolute;
  top: 50%;
  left: 12px;
  transform: translateY(-50%);
  color: #888;
  font-size: 18px;
  pointer-events: none;
}
.products-search input {
  width: 100%;
  height: 42px;
  padding: 0 13px 0 38px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.products-search input::placeholder {
  color: #999;
}
.products-search input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

/*
|--------------------------------------------------------------------------
| Filters
|--------------------------------------------------------------------------
*/
.products-filter-group {
  display: flex;
  align-items: center;
  gap: 10px;
}
.products-filter-group select {
  min-width: 145px;
  height: 42px;
  padding: 0 32px 0 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
}
.products-filter-group select:focus {
  border-color: rgba(23, 114, 69, 0.5);
}

/*
|--------------------------------------------------------------------------
| Table
|--------------------------------------------------------------------------
*/
.products-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.products-table {
  width: 100%;
  min-width: 1250px;
  border-collapse: collapse;
}
.products-table th,
.products-table td {
  padding: 14px 13px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
}
.products-table th {
  background: #F2F4F7;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  white-space: nowrap;
}
.products-table td {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.products-table tbody tr {
  transition: 0.15s;
}
.products-table tbody tr:hover {
  background: rgba(23, 114, 69, 0.018);
}
.products-table tbody tr:last-child td {
  border-bottom: 0;
}
.products-table__check {
  width: 45px;
}

/*
|--------------------------------------------------------------------------
| Checkbox
|--------------------------------------------------------------------------
*/
.products-checkbox {
  width: 16px;
  height: 16px;
  margin: 0;
  accent-color: #177245;
  cursor: pointer;
}

/*
|--------------------------------------------------------------------------
| Product
|--------------------------------------------------------------------------
*/
.product-table-product {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 240px;
}
.product-table-product__image {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #F2F4F7;
}
.product-table-product__image img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}
.product-table-product__info {
  min-width: 0;
}
.product-table-product__info a {
  display: block;
  margin-bottom: 4px;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-decoration: none;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.product-table-product__info a:hover {
  color: #177245;
}
.product-table-product__info span {
  display: block;
  color: #888;
  font-size: 14px;
  line-height: 1.4;
}

/*
|--------------------------------------------------------------------------
| Source Badge
|--------------------------------------------------------------------------
*/
.product-source-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 28px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
  white-space: nowrap;
}
.product-source-badge i {
  font-size: 15px;
}
.product-source-badge--own {
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
}
.product-source-badge--amazon {
  background: rgba(255, 193, 7, 0.11);
  color: #947000;
}
.product-source-badge--aliexpress {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}

/*
|--------------------------------------------------------------------------
| Price
|--------------------------------------------------------------------------
*/
.product-price strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
}
.product-price span {
  display: block;
  margin-top: 2px;
  color: #999;
  font-size: 14px;
  line-height: 1.4;
  text-decoration: line-through;
}

/*
|--------------------------------------------------------------------------
| Stock
|--------------------------------------------------------------------------
*/
.product-stock {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
}
.product-stock--available {
  background: rgba(25, 135, 84, 0.09);
  color: #198754;
}
.product-stock--low {
  background: rgba(255, 193, 7, 0.11);
  color: #947000;
}
.product-stock--out {
  background: rgba(220, 53, 69, 0.09);
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Variant Badge
|--------------------------------------------------------------------------
*/
.product-variant-badge {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 9px;
  border-radius: 20px;
  background: rgba(23, 114, 69, 0.06);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Status
|--------------------------------------------------------------------------
*/
.product-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}
.product-status i {
  width: 7px;
  height: 7px;
  display: inline-block;
  border-radius: 50%;
}
.product-status--active {
  color: #198754;
}
.product-status--active i {
  background: #198754;
}
.product-status--inactive {
  color: #dc3545;
}
.product-status--inactive i {
  background: #dc3545;
}
.product-status--draft {
  color: #947000;
}
.product-status--draft i {
  background: #ffc107;
}

/*
|--------------------------------------------------------------------------
| Actions
|--------------------------------------------------------------------------
*/
.product-actions {
  display: flex;
  align-items: center;
  gap: 5px;
}

.product-action-btn {
  width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-size: 16px;
  cursor: pointer;
  transition: 0.2s;
}
.product-action-btn:hover {
  border-color: rgba(23, 114, 69, 0.4);
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
}
.product-action-btn--danger:hover {
  border-color: rgba(220, 53, 69, 0.25);
  background: rgba(220, 53, 69, 0.06);
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Pagination
|--------------------------------------------------------------------------
*/
.products-pagination {
  display: flex;
  align-items: center;
  gap: 5px;
}
.products-pagination button {
  min-width: 34px;
  height: 34px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 8px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
}
.products-pagination button:hover {
  border-color: rgba(23, 114, 69, 0.4);
  color: #177245;
}
.products-pagination button.active {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.products-pagination button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.products-pagination span {
  padding: 0 3px;
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Responsive
|--------------------------------------------------------------------------
*/
@media (min-width: 1400px) and (max-width: 1700px) {
  .products-summary {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (min-width: 1200px) and (max-width: 1399px) {
  .products-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .products-card__filters {
    align-items: stretch;
    flex-direction: column;
  }
  .products-search {
    width: 100%;
  }
  .products-filter-group {
    width: 100%;
  }
  .products-filter-group select {
    flex: 1;
    width: 100%;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .products-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .products-page__header {
    align-items: flex-start;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .products-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .products-page__add-btn {
    width: 100%;
  }
  .products-filter-group {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .products-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }
  .products-pagination {
    width: 100%;
    justify-content: center;
  }
}
@media (max-width: 767px) {
  .products-page h1 {
    font-size: 24px;
  }
  .products-summary {
    grid-template-columns: 1fr;
  }
  .products-card__filters {
    padding: 15px;
  }
  .products-filter-group {
    grid-template-columns: 1fr;
  }
  .products-card__footer {
    padding: 15px;
  }
}
/*
|--------------------------------------------------------------------------
| Product Create Page
|--------------------------------------------------------------------------
*/
.product-create-page {
  width: 100%;
  /*
  |--------------------------------------------------------------------------
  | Header
  |--------------------------------------------------------------------------
  */
}
.product-create-page__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
}
.product-create-page__header h1 {
  margin: 4px 0 6px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.product-create-page__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}
.product-create-page__eyebrow {
  display: block;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.product-create-page__back {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 15px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.product-create-page__back i {
  font-size: 18px;
}
.product-create-page__back:hover {
  border-color: rgba(23, 114, 69, 0.4);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Layout
|--------------------------------------------------------------------------
*/
.product-create-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: 20px;
}

.product-create-main {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.product-create-sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Form Card
|--------------------------------------------------------------------------
*/
.product-form-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}
.product-form-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 19px 20px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.product-form-card__header h4 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
}
.product-form-card__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.product-form-card__body {
  padding: 20px;
}
.product-form-card__body--table {
  padding: 0;
}

/*
|--------------------------------------------------------------------------
| Product Source
|--------------------------------------------------------------------------
*/
.product-source-options {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.product-source-option {
  position: relative;
  display: block;
  min-width: 0;
  padding: 17px;
  border: 1px solid #ddd;
  border-radius: 10px;
  background: #fff;
  cursor: pointer;
  transition: 0.2s;
}
.product-source-option input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}
.product-source-option__content {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding-right: 25px;
}
.product-source-option__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  font-size: 20px;
}
.product-source-option__icon.amazon {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.product-source-option__icon.aliexpress {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}
.product-source-option__text {
  min-width: 0;
}
.product-source-option__text strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 600;
}
.product-source-option__text > span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.product-source-option__check {
  position: absolute;
  top: 15px;
  right: 15px;
  width: 22px;
  height: 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 50%;
  background: #fff;
  color: #fff;
  font-size: 14px;
}
.product-source-option:has(input:checked) {
  border-color: #177245;
  background: rgba(23, 114, 69, 0.025);
  box-shadow: 0 0 0 1px rgba(23, 114, 69, 0.08);
}
.product-source-option:has(input:checked) .product-source-option__check {
  border-color: #177245;
  background: #177245;
}
.product-source-option:hover {
  border-color: rgba(23, 114, 69, 0.4);
}

/*
|--------------------------------------------------------------------------
| Form Groups
|--------------------------------------------------------------------------
*/
.product-form-group {
  margin-bottom: 18px;
}
.product-form-group:last-child {
  margin-bottom: 0;
}
.product-form-group label {
  display: block;
  margin-bottom: 8px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.product-form-group label span {
  color: #dc3545;
}
.product-form-group input,
.product-form-group select,
.product-form-group textarea {
  width: 100%;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s;
}
.product-form-group input::placeholder,
.product-form-group select::placeholder,
.product-form-group textarea::placeholder {
  color: #999;
}
.product-form-group input:focus,
.product-form-group select:focus,
.product-form-group textarea:focus {
  border-color: rgba(23, 114, 69, 0.55);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.07);
}
.product-form-group input,
.product-form-group select {
  height: 44px;
  padding: 0 13px;
}
.product-form-group textarea {
  min-height: 130px;
  padding: 12px 13px;
  resize: vertical;
  line-height: 1.6;
}

.product-form-row {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.product-form-help {
  display: block;
  margin-top: 7px;
  color: #888;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Prefix / Suffix
|--------------------------------------------------------------------------
*/
.product-input-prefix,
.product-input-suffix {
  position: relative;
}
.product-input-prefix input,
.product-input-suffix input {
  padding-left: 38px;
}

.product-input-prefix span {
  position: absolute;
  top: 50%;
  left: 13px;
  z-index: 1;
  transform: translateY(-50%);
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  pointer-events: none;
}

.product-input-suffix input {
  padding-right: 42px;
}
.product-input-suffix span {
  position: absolute;
  top: 50%;
  right: 13px;
  transform: translateY(-50%);
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  pointer-events: none;
}

/*
|--------------------------------------------------------------------------
| Product Media
|--------------------------------------------------------------------------
*/
.product-media-section {
  margin-bottom: 25px;
}
.product-media-section:last-child {
  margin-bottom: 0;
}
.product-media-section__title {
  margin-bottom: 12px;
}
.product-media-section__title strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.product-media-section__title span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.product-main-image-upload {
  position: relative;
  min-height: 210px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  padding: 25px;
  border: 1px dashed rgba(23, 114, 69, 0.4);
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.025);
  text-align: center;
  cursor: pointer;
}
.product-main-image-upload__icon {
  width: 55px;
  height: 55px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 10px;
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.09);
  color: #177245;
  font-size: 25px;
}
.product-main-image-upload strong {
  margin-bottom: 5px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
}
.product-main-image-upload span {
  color: #555555;
  font-size: 14px;
}
.product-main-image-upload input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

.product-gallery-upload {
  position: relative;
  display: flex;
  align-items: center;
  gap: 15px;
  padding: 20px;
  border: 1px dashed #ddd;
  border-radius: 10px;
  background: #F2F4F7;
  cursor: pointer;
}
.product-gallery-upload__icon {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: #fff;
  color: #177245;
  font-size: 22px;
}
.product-gallery-upload__content {
  min-width: 0;
}
.product-gallery-upload__content strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
}
.product-gallery-upload__content span {
  display: block;
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.product-gallery-upload__content small {
  display: block;
  color: #888;
  font-size: 14px;
}
.product-gallery-upload input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  opacity: 0;
  cursor: pointer;
}

/*
|--------------------------------------------------------------------------
| Variant Toggle
|--------------------------------------------------------------------------
*/
.product-variant-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px;
  margin-bottom: 25px;
  border: 1px solid rgba(23, 114, 69, 0.18);
  border-radius: 10px;
  background: rgba(23, 114, 69, 0.035);
}
.product-variant-toggle__content {
  min-width: 0;
}
.product-variant-toggle__content strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 600;
}
.product-variant-toggle__content span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Switch
|--------------------------------------------------------------------------
*/
.product-switch {
  position: relative;
  width: 46px;
  height: 25px;
  flex: 0 0 46px;
  display: inline-block;
}
.product-switch input {
  width: 1px !important;
  height: 1px !important;
  opacity: 0;
  position: absolute;
}
.product-switch__slider {
  position: absolute;
  inset: 0;
  border-radius: 30px;
  background: #ddd;
  cursor: pointer;
  transition: 0.2s;
}
.product-switch__slider::before {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 19px;
  height: 19px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 1px 3px rgba(16, 26, 35, 0.15);
  transition: 0.2s;
}
.product-switch input:checked + .product-switch__slider {
  background: #177245;
}
.product-switch input:checked + .product-switch__slider::before {
  transform: translateX(21px);
}
.product-switch--small {
  width: 38px;
  height: 21px;
}
.product-switch--small .product-switch__slider::before {
  width: 15px;
  height: 15px;
}
.product-switch--small input:checked + .product-switch__slider::before {
  transform: translateX(17px);
}

/*
|--------------------------------------------------------------------------
| Variant Builder
|--------------------------------------------------------------------------
*/
.product-variant-builder {
  padding-top: 5px;
}
.product-variant-builder__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  margin-bottom: 18px;
}
.product-variant-builder__header h5 {
  margin: 0 0 4px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
}
.product-variant-builder__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.product-add-attribute-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid rgba(23, 114, 69, 0.3);
  border-radius: 7px;
  background: rgba(23, 114, 69, 0.05);
  color: #177245;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.product-add-attribute-btn i {
  font-size: 17px;
}

.product-attribute-item {
  padding: 18px;
  margin-bottom: 15px;
  border: 1px solid #ddd;
  border-radius: 10px;
  background: #fff;
}
.product-attribute-item__top {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: flex-end;
  gap: 12px;
  margin-bottom: 18px;
}
.product-attribute-item__top .product-form-group {
  margin-bottom: 0;
}

.product-remove-attribute-btn {
  width: 42px;
  height: 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(220, 53, 69, 0.2);
  border-radius: 8px;
  background: rgba(220, 53, 69, 0.05);
  color: #dc3545;
  font-size: 17px;
  cursor: pointer;
}

.product-value-input {
  display: flex;
  gap: 8px;
}
.product-value-input input {
  flex: 1;
  width: 100%;
  height: 42px;
  padding: 0 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  color: #0D2B5A;
