/*
|--------------------------------------------------------------------------
| Generate Variations
|--------------------------------------------------------------------------
*/
.product-generate-variations {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 16px;
  margin-top: 20px;
