}
.product-generate-variations strong {
  display: block;
  margin-bottom: 4px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
}
.product-generate-variations span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.product-generate-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 15px;
  border: 1px solid #177245;
  border-radius: 8px;
  background: #177245;
  color: #fff;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
}
.product-generate-btn i {
  font-size: 17px;
}

/*
|--------------------------------------------------------------------------
| Variation Table
|--------------------------------------------------------------------------
*/
.product-variation-count {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 10px;
  border-radius: 20px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
}

.product-variation-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.product-variation-table {
  width: 100%;
  min-width: 950px;
  border-collapse: collapse;
}
.product-variation-table th,
.product-variation-table td {
  padding: 12px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
}
.product-variation-table th {
  background: #F2F4F7;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.product-variation-table td {
  background: #fff;
}
.product-variation-table tbody tr:last-child td {
  border-bottom: 0;
}
.product-variation-table input {
  width: 100%;
  min-width: 80px;
  height: 38px;
  padding: 0 9px;
  border: 1px solid #ddd;
  border-radius: 7px;
  outline: none;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
}
.product-variation-table input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

.product-variation-name {
  min-width: 150px;
}
.product-variation-name strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.product-variation-name span {
  display: block;
  color: #888;
  font-size: 14px;
  line-height: 1.4;
}

.product-table-price {
  position: relative;
}
.product-table-price span {
  position: absolute;
  top: 50%;
  left: 9px;
  transform: translateY(-50%);
  color: #555555;
  font-size: 14px;
  pointer-events: none;
}
.product-table-price input {
  padding-left: 23px;
}

.product-variation-image {
  position: relative;
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px dashed #ddd;
  border-radius: 7px;
  background: #F2F4F7;
  color: #177245;
  cursor: pointer;
}
.product-variation-image i {
  font-size: 18px;
}
.product-variation-image input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  min-width: 0;
  opacity: 0;
  cursor: pointer;
}

.product-remove-row-btn {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(220, 53, 69, 0.2);
  border-radius: 7px;
  background: rgba(220, 53, 69, 0.06);
  color: #dc3545;
  font-size: 17px;
  cursor: pointer;
}

/*
|--------------------------------------------------------------------------
| Publish
|--------------------------------------------------------------------------
*/
.product-publish-status {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 15px;
  margin-bottom: 15px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
}
.product-publish-status span {
  color: #555555;
  font-size: 14px;
}
.product-publish-status strong {
  display: inline-flex;
  align-items: center;
  min-height: 28px;
  padding: 4px 10px;
  border-radius: 20px;
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
  font-size: 14px;
  font-weight: 600;
}

.product-publish-info {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 12px;
  margin-bottom: 18px;
  border-radius: 8px;
  background: #F2F4F7;
}
.product-publish-info i {
  flex: 0 0 auto;
  margin-top: 1px;
  color: #177245;
  font-size: 18px;
}
.product-publish-info span {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

.product-publish-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

/*
|--------------------------------------------------------------------------
| Buttons
|--------------------------------------------------------------------------
*/
.product-btn {
  width: 100%;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.product-btn--primary {
  border: 1px solid #177245;
  background: #177245;
  color: #fff;
}
.product-btn--primary:hover {
  background: rgba(23, 114, 69, 0.85);
  color: #fff;
}
.product-btn--secondary {
  border: 1px solid #ddd;
  background: #fff;
  color: #555555;
}
.product-btn--secondary:hover {
  border-color: rgba(23, 114, 69, 0.4);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Sidebar
|--------------------------------------------------------------------------
*/
.product-source-reminder,
.product-create-help {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 18px;
  border-radius: 12px;
}

.product-source-reminder {
  border: 1px solid rgba(13, 202, 240, 0.25);
  background: rgba(13, 202, 240, 0.06);
}
.product-source-reminder__icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
  font-size: 20px;
}

.product-create-help {
  border: 1px solid rgba(212, 175, 55, 0.25);
  background: rgba(212, 175, 55, 0.06);
}
.product-create-help__icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(212, 175, 55, 0.12);
  color: #D4AF37;
  font-size: 20px;
}

.product-source-reminder strong,
.product-create-help strong {
  display: block;
  margin-bottom: 5px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
}

.product-source-reminder p,
.product-create-help p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*
|--------------------------------------------------------------------------
| Responsive
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .product-create-layout {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
  .product-source-options {
    grid-template-columns: 1fr;
  }
}
@media (min-width: 992px) and (max-width: 1199px) {
  .product-create-layout {
    grid-template-columns: 1fr;
  }
  .product-create-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .product-create-sidebar .product-form-card:first-child {
    grid-column: span 2;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .product-create-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-create-page__back {
    width: 100%;
  }
  .product-create-sidebar {
    display: flex;
  }
  .product-form-row {
    grid-template-columns: 1fr;
  }
  .product-source-options {
    grid-template-columns: 1fr;
  }
  .product-variant-toggle {
    align-items: flex-start;
  }
  .product-variant-builder__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-generate-variations {
    align-items: flex-start;
    flex-direction: column;
  }
  .product-gallery-upload {
    align-items: flex-start;
    flex-direction: column;
  }
}
@media (max-width: 767px) {
  .product-create-page__header h1 {
    font-size: 24px;
  }
  .product-form-card__header,
  .product-form-card__body {
    padding: 16px;
  }
  .product-source-option {
    padding: 15px;
  }
  .product-attribute-item {
    padding: 14px;
  }
  .product-variant-toggle {
    flex-direction: column;
  }
  .product-switch {
    align-self: flex-start;
  }
  .product-attribute-item__top {
    grid-template-columns: 1fr;
  }
  .product-remove-attribute-btn {
    width: 100%;
  }
}
/*
|--------------------------------------------------------------------------
| Product Details Page
|--------------------------------------------------------------------------
*/
.product-details-page {
  width: 100%;
  /*
  |--------------------------------------------------------------------------
  | Header
  |--------------------------------------------------------------------------
  */
}
.product-details-page__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 25px;
}
.product-details-page__eyebrow {
  display: block;
  margin-bottom: 7px;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  letter-spacing: 0.03em;
}
.product-details-page__title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
}
.product-details-page__title-row h1 {
