}

/*
|--------------------------------------------------------------------------
| Overview
|--------------------------------------------------------------------------
*/
.category-details-overview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 20px;
  margin-bottom: 20px;
}
.category-details-overview__main {
  display: flex;
  flex-direction: column;
  gap: 20px;
}
.category-details-overview__sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.category-details-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}
.category-details-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 18px 20px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.category-details-card__header h4 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
}
.category-details-card__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.category-details-card__body {
  padding: 20px;
}

/*
|--------------------------------------------------------------------------
| Category Info
|--------------------------------------------------------------------------
*/
.category-info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px;
}

.category-info-item {
  min-width: 0;
}
.category-info-item--full {
  grid-column: 1/-1;
}
.category-info-item span {
  display: block;
  margin-bottom: 6px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.category-info-item strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.5;
  font-weight: 600;
  word-break: break-word;
}
.category-info-item p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.65;
}

/*
|--------------------------------------------------------------------------
| Category Image
|--------------------------------------------------------------------------
*/
.category-details-image {
  overflow: hidden;
  width: 100%;
  border-radius: 10px;
  background: #f6f7f8;
}
.category-details-image img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 16/8;
  object-fit: cover;
}

/*
|--------------------------------------------------------------------------
| Statistics
|--------------------------------------------------------------------------
*/
.category-stat-list {
  display: flex;
  flex-direction: column;
}

.category-stat-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 0;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.category-stat-item:first-child {
  padding-top: 0;
}
.category-stat-item:last-child {
  padding-bottom: 0;
  border-bottom: 0;
}
.category-stat-item__icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 18px;
}
.category-stat-item span {
  display: block;
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.category-stat-item strong {
  display: block;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
}
.category-stat-item__success {
  color: #198754 !important;
}

/*
|--------------------------------------------------------------------------
| Dates
|--------------------------------------------------------------------------
*/
.category-date-list {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.category-date-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
}
.category-date-item span {
  color: #555555;
  font-size: 14px;
}
.category-date-item strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}

/*
|--------------------------------------------------------------------------
| Status Box
|--------------------------------------------------------------------------
*/
.category-status-box {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 13px;
  border: 1px solid rgba(25, 135, 84, 0.2);
  border-radius: 9px;
  background: rgba(25, 135, 84, 0.05);
}
.category-status-box__icon {
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
  font-size: 18px;
}
.category-status-box strong {
  display: block;
  margin-bottom: 3px;
  color: #198754;
  font-size: 14px;
  font-weight: 700;
}
.category-status-box span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Count Badge
|--------------------------------------------------------------------------
*/
.category-details-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 30px;
  padding: 0 10px;
  border-radius: 20px;
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Subcategories
|--------------------------------------------------------------------------
*/
.category-subcategories {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.category-subcategory {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 0;
  padding: 13px;
  border: 1px solid #ddd;
  border-radius: 9px;
  transition: 0.2s;
}
.category-subcategory:hover {
  border-color: rgba(23, 114, 69, 0.35);
}
.category-subcategory__icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(23, 114, 69, 0.07);
  color: #177245;
  font-size: 18px;
}
.category-subcategory__content {
  flex: 1;
  min-width: 0;
}
.category-subcategory__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.category-subcategory__content span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}

/*
|--------------------------------------------------------------------------
| Product Summary
|--------------------------------------------------------------------------
*/
.category-product-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 15px;
}

.category-product-summary__item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px;
  border: 1px solid #ddd;
  border-radius: 9px;
}
.category-product-summary__item > div:last-child {
  min-width: 0;
}
.category-product-summary__item span {
  display: block;
  margin-bottom: 3px;
  color: #555555;
  font-size: 14px;
}
.category-product-summary__item strong {
  display: block;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 700;
}

.category-product-summary__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  background: rgba(25, 135, 84, 0.08);
  color: #198754;
  font-size: 19px;
}
.category-product-summary__icon--warning {
  background: rgba(255, 193, 7, 0.1);
  color: #ffc107;
}
.category-product-summary__icon--danger {
  background: rgba(220, 53, 69, 0.08);
  color: #dc3545;
}

/*
|--------------------------------------------------------------------------
| Responsive
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .category-details-overview {
    grid-template-columns: minmax(0, 1fr) 290px;
  }
  .category-subcategories {
    grid-template-columns: 1fr;
  }
}
@media (min-width: 768px) and (max-width: 991px) {
  .category-details-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .category-details-page__actions {
    width: 100%;
  }
  .category-details-btn {
    flex: 1;
  }
  .category-details-overview {
    grid-template-columns: 1fr;
  }
  .category-details-overview__sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .category-details-overview__sidebar .category-details-card:last-child {
    grid-column: 1/-1;
  }
  .category-product-summary {
    grid-template-columns: 1fr;
  }
}
@media (min-width: 480px) and (max-width: 767px) {
  .category-details-page__title-row {
    align-items: flex-start;
  }
  .category-details-page__title {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }
  .category-details-page__actions {
    flex-direction: column;
  }
  .category-details-btn {
    width: 100%;
  }
  .category-details-overview__sidebar {
    display: flex;
  }
  .category-info-grid {
    grid-template-columns: 1fr;
  }
  .category-info-item--full {
    grid-column: auto;
  }
  .category-details-card__header,
  .category-details-card__body {
    padding: 16px;
  }
  .category-subcategories {
    grid-template-columns: 1fr;
  }
  .category-subcategory {
    flex-wrap: wrap;
  }
  .category-subcategory .category-details-status {
    margin-left: 51px;
  }
}
