}
.category-edit-page__header h1 {
  margin: 0;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.category-edit-page__header p {
  margin: 7px 0 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.category-edit-page__header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}
.category-edit-page__back-btn {
  display: inline-flex;
  align-items: center;
