}
.category-edit-page__back-btn i {
  font-size: 17px;
}
.category-edit-page__back-btn:hover {
  border-color: rgba(23, 114, 69, 0.4);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.category-edit-card {
  overflow: hidden;
  margin-bottom: 20px;
  border: 1px solid #ddd;
  border-radius: 12px;
