.orders-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 22px;
}

.orders-stat-card {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  padding: 17px;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
  transition: 0.2s;
}
.orders-stat-card:hover {
  border-color: rgba(23, 114, 69, 0.3);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.04);
}
.orders-stat-card__icon {
  width: 44px;
  height: 44px;
