  |--------------------------------------------------------------------------
  | Header
  |--------------------------------------------------------------------------
  */
}
.order-details-page__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 25px;
  margin-bottom: 22px;
}
.order-details-page__eyebrow {
  display: block;
  margin-bottom: 5px;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

/*
|--------------------------------------------------------------------------
| Back
|--------------------------------------------------------------------------
*/
.order-details-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 15px;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.order-details-back i {
  font-size: 17px;
}
.order-details-back:hover {
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Title
|--------------------------------------------------------------------------
*/
.order-details-title {
  display: flex;
  align-items: center;
  gap: 15px;
}
.order-details-title h1 {
  margin: 0 0 5px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.order-details-title p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Main Status
|--------------------------------------------------------------------------
*/
.order-details-main-status {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 30px;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 14px;
  line-height: 1.3;
  font-weight: 600;
  white-space: nowrap;
}
.order-details-main-status i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}
.order-details-main-status--processing {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}

/*
|--------------------------------------------------------------------------
| Header Actions
|--------------------------------------------------------------------------
*/
.order-details-page__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.order-details-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}
.order-details-action-btn i {
  font-size: 17px;
}
.order-details-action-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}
.order-details-action-btn--primary {
  border-color: #177245;
  background: #177245;
  color: #fff;
}
.order-details-action-btn--primary:hover {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

/*
|--------------------------------------------------------------------------
| Summary
|--------------------------------------------------------------------------
*/
.order-details-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  margin-bottom: 20px;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}

.order-details-summary__item {
  padding: 17px 18px;
  border-right: 1px solid rgba(221, 221, 221, 0.7);
}
.order-details-summary__item:last-child {
  border-right: 0;
}
.order-details-summary__item span {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.order-details-summary__item strong {
  display: block;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.3;
  font-weight: 700;
}

.order-details-summary__paid {
  color: #198754 !important;
}

/*
|--------------------------------------------------------------------------
| Main Grid
|--------------------------------------------------------------------------
*/
.order-details-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: 20px;
}

.order-details-main,
.order-details-sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.order-details-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}
.order-details-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.order-details-card__header h2 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.order-details-card__header span {
  display: block;
  margin-top: 3px;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Order Items
|--------------------------------------------------------------------------
*/
.order-items-table-wrapper {
  overflow-x: auto;
}

.order-items-table {
  width: 100%;
  min-width: 650px;
  border-collapse: collapse;
}
.order-items-table th,
.order-items-table td {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
  vertical-align: middle;
  font-size: 14px;
}
.order-items-table th {
  background: #F2F4F7;
  color: #555555;
  font-weight: 600;
  white-space: nowrap;
}
.order-items-table td {
  color: #555555;
}
.order-items-table tbody tr:last-child td {
  border-bottom: 0;
}

/*
|--------------------------------------------------------------------------
| Product
|--------------------------------------------------------------------------
*/
.order-product {
  display: flex;
  align-items: center;
  gap: 11px;
  min-width: 270px;
}
.order-product__image {
  width: 52px;
  height: 52px;
  flex: 0 0 52px;
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #f7f7f7;
}
.order-product__image img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.order-product__content {
  min-width: 0;
}
.order-product__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.order-product__content span {
  display: block;
  margin-bottom: 2px;
  color: #555555;
  font-size: 14px;
}
.order-product__content small {
  display: block;
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Quantity
|--------------------------------------------------------------------------
*/
.order-item-quantity {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid #ddd;
  border-radius: 6px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*
|--------------------------------------------------------------------------
| Order Totals
|--------------------------------------------------------------------------
*/
.order-total-list {
  padding: 5px 18px;
}

.order-total-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 13px 0;
  border-bottom: 1px solid rgba(221, 221, 221, 0.6);
}
.order-total-row:last-child {
  border-bottom: 0;
}
.order-total-row span {
  color: #555555;
  font-size: 14px;
}
.order-total-row strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.order-total-row--grand {
  padding-top: 17px;
}
.order-total-row--grand span {
  color: #0D2B5A;
  font-weight: 700;
}
.order-total-row--grand strong {
  color: #177245;
  font-size: 20px;
}

/*
|--------------------------------------------------------------------------
| Shipment
|--------------------------------------------------------------------------
*/
.order-shipment-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
}
.order-shipment-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.order-shipment-status--pending {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}

.order-shipment-box {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0;
  padding: 17px 18px;
}

.order-shipment-info {
  padding-right: 15px;
  border-right: 1px solid rgba(221, 221, 221, 0.7);
}
.order-shipment-info:last-child {
  padding-right: 0;
  padding-left: 15px;
  border-right: 0;
}
.order-shipment-info:not(:first-child) {
  padding-left: 15px;
}
.order-shipment-info span {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.order-shipment-info strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}

.order-shipment-action {
  padding: 0 18px 17px;
}

.order-details-secondary-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 39px;
  padding: 0 13px;
  border: 1px solid #ddd;
  border-radius: 7px;
  background: #fff;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.order-details-secondary-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Customer
|--------------------------------------------------------------------------
*/
.order-customer-profile {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 17px 18px;
}
.order-customer-profile__avatar {
  width: 48px;
  height: 48px;
  flex: 0 0 48px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 14px;
  font-weight: 700;
}
.order-customer-profile strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.order-customer-profile span {
  display: block;
  color: #555555;
  font-size: 14px;
}

.order-customer-contact {
  padding: 0 18px 17px;
}
.order-customer-contact > div {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 11px;
  margin-top: 11px;
  border-top: 1px solid rgba(221, 221, 221, 0.6);
}
.order-customer-contact > div i {
  color: #177245;
  font-size: 17px;
}
.order-customer-contact > div span {
  overflow: hidden;
  color: #555555;
  font-size: 14px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/*
|--------------------------------------------------------------------------
| Address
|--------------------------------------------------------------------------
*/
.order-address {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 17px 18px;
}
.order-address strong {
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.order-address span {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Payment
|--------------------------------------------------------------------------
*/
.order-payment-details {
  padding: 5px 18px;
}
.order-payment-details > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 12px 0;
  border-bottom: 1px solid rgba(221, 221, 221, 0.6);
}
.order-payment-details > div:last-child {
  border-bottom: 0;
}
.order-payment-details > div > span:first-child {
  color: #555555;
  font-size: 14px;
}
.order-payment-details > div strong {
  max-width: 180px;
  overflow: hidden;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.order-payment-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 26px;
  padding: 4px 8px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 600;
}
.order-payment-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.order-payment-status--paid {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}

/*
|--------------------------------------------------------------------------
| Note
|--------------------------------------------------------------------------
*/
.order-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 17px 18px;
}
.order-note i {
  margin-top: 2px;
  color: #177245;
  font-size: 17px;
}
.order-note p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*
|--------------------------------------------------------------------------
| Responsive XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .order-details-grid {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
  .order-shipment-box {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 15px;
  }
  .order-shipment-info {
    padding: 0 0 10px !important;
    border-right: 0 !important;
    border-bottom: 1px solid rgba(221, 221, 221, 0.6);
  }
  .order-shipment-info:nth-last-child(-n+2) {
    padding-bottom: 0 !important;
    border-bottom: 0 !important;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .order-details-grid {
    grid-template-columns: 1fr;
  }
  .order-details-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/*
|--------------------------------------------------------------------------
| Responsive MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .order-details-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .order-details-page__actions {
    width: 100%;
  }
  .order-details-action-btn {
    flex: 1;
  }
  .order-details-title {
    align-items: flex-start;
    flex-direction: column;
  }
  .order-details-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .order-details-summary__item {
    border-right: 0;
    border-bottom: 1px solid rgba(221, 221, 221, 0.7);
  }
  .order-details-summary__item:nth-child(odd) {
    border-right: 1px solid rgba(221, 221, 221, 0.7);
  }
  .order-details-summary__item:nth-last-child(-n+2) {
    border-bottom: 0;
  }
  .order-details-sidebar {
    grid-template-columns: 1fr;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .order-details-page__header {
    margin-bottom: 18px;
  }
  .order-details-title h1 {
    font-size: 24px;
  }
  .order-details-summary {
    grid-template-columns: 1fr;
  }
  .order-details-summary__item {
    border-right: 0 !important;
    border-bottom: 1px solid rgba(221, 221, 221, 0.7);
  }
  .order-details-summary__item:last-child {
    border-bottom: 0;
  }
  .order-details-page__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .order-details-action-btn {
    width: 100%;
    padding: 0 9px;
  }
  .order-details-card__header {
    padding: 14px;
  }
  .order-total-list {
    padding: 5px 14px;
  }
  .order-shipment-box {
    grid-template-columns: 1fr;
    padding: 14px;
  }
  .order-shipment-info {
    padding: 10px 0 !important;
    border-right: 0 !important;
    border-bottom: 1px solid rgba(221, 221, 221, 0.6);
  }
  .order-shipment-info:last-child {
    padding-bottom: 0 !important;
    border-bottom: 0 !important;
  }
  .order-shipment-action {
    padding: 0 14px 14px;
  }
  .order-customer-profile {
    padding: 14px;
  }
  .order-customer-contact {
    padding: 0 14px 14px;
  }
  .order-address {
    padding: 14px;
  }
  .order-payment-details {
    padding: 5px 14px;
  }
  .order-note {
    padding: 14px;
  }
}
/*
|--------------------------------------------------------------------------
| Payments Page
|--------------------------------------------------------------------------
*/
.payments-page {
  width: 100%;
  /*
  |--------------------------------------------------------------------------
  | Header
  |--------------------------------------------------------------------------
  */
}
.payments-page__header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 25px;
}
.payments-page__eyebrow {
  display: block;
  margin-bottom: 5px;
  color: #177245;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}
.payments-page__header h1 {
  margin: 0 0 6px;
  color: #0D2B5A;
  font-size: 24px;
  line-height: 1.3;
  font-weight: 700;
}
.payments-page__header p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Export Button
|--------------------------------------------------------------------------
*/
.payments-export-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 14px;
  border: 1px solid #ddd;
  border-radius: 8px;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}
.payments-export-btn i {
  font-size: 17px;
}
.payments-export-btn:hover {
  border-color: rgba(23, 114, 69, 0.35);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Stats
|--------------------------------------------------------------------------
*/
.payments-stats {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  margin-bottom: 22px;
}

.payments-stat-card {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
  padding: 17px;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
  transition: 0.2s;
}
.payments-stat-card:hover {
  border-color: rgba(23, 114, 69, 0.3);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.04);
}
.payments-stat-card__icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 20px;
}
.payments-stat-card__icon--success {
  background: rgba(25, 135, 84, 0.1);
  color: #198754;
}
.payments-stat-card__icon--warning {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}
.payments-stat-card__icon--danger {
  background: rgba(220, 53, 69, 0.1);
  color: #dc3545;
}
.payments-stat-card span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.4;
}
.payments-stat-card strong {
  display: block;
  color: #0D2B5A;
  font-size: 20px;
  line-height: 1.2;
  font-weight: 700;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.payments-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: #fff;
}

/*
|--------------------------------------------------------------------------
| Toolbar
|--------------------------------------------------------------------------
*/
.payments-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 17px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.payments-toolbar__filters {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/*
|--------------------------------------------------------------------------
| Search
|--------------------------------------------------------------------------
*/
.payments-search {
  position: relative;
  width: 100%;
  max-width: 360px;
}
.payments-search i {
  position: absolute;
  top: 50%;
  left: 12px;
  transform: translateY(-50%);
  color: #888;
  font-size: 17px;
  pointer-events: none;
}
.payments-search input {
  width: 100%;
  height: 42px;
  padding: 0 12px 0 38px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s;
}
.payments-search input::placeholder {
  color: #999;
}
.payments-search input:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}

/*
|--------------------------------------------------------------------------
| Filters
|--------------------------------------------------------------------------
*/
.payments-filter {
  height: 42px;
  min-width: 145px;
  padding: 0 12px;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #555555;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  cursor: pointer;
}
.payments-filter:focus {
  border-color: rgba(23, 114, 69, 0.5);
}

/*
|--------------------------------------------------------------------------
| Table Wrapper
|--------------------------------------------------------------------------
*/
.payments-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

/*
|--------------------------------------------------------------------------
| Table
|--------------------------------------------------------------------------
*/
.payments-table {
  width: 100%;
