/*
|--------------------------------------------------------------------------
| Main Grid
|--------------------------------------------------------------------------
*/
.shipment-create-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  align-items: start;
  gap: 20px;
}

.shipment-create-main,
.shipment-create-sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.shipment-create-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}
.shipment-create-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.shipment-create-card__header h2 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.shipment-create-card__header span {
  display: block;
  margin-top: 3px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.shipment-create-card__body {
  padding: 18px;
}

/*
|--------------------------------------------------------------------------
| Form Grid
|--------------------------------------------------------------------------
*/
.shipment-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 17px;
}

/*
|--------------------------------------------------------------------------
| Form Group
|--------------------------------------------------------------------------
*/
.shipment-form-group {
  display: flex;
  flex-direction: column;
}
.shipment-form-group--full {
  grid-column: 1/-1;
}
.shipment-form-group label {
  display: block;
  margin-bottom: 7px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.shipment-form-group label span {
  color: #dc3545;
}
.shipment-form-group input,
.shipment-form-group select,
.shipment-form-group textarea {
  width: 100%;
  border: 1px solid #ddd;
  border-radius: 8px;
  outline: none;
  background: #fff;
  color: #0D2B5A;
  font-family: "Poppins", sans-serif;
  font-size: 14px;
  transition: 0.2s;
}
.shipment-form-group input::placeholder,
.shipment-form-group select::placeholder,
.shipment-form-group textarea::placeholder {
  color: #999;
}
.shipment-form-group input:focus,
.shipment-form-group select:focus,
.shipment-form-group textarea:focus {
  border-color: rgba(23, 114, 69, 0.5);
  box-shadow: 0 0 0 3px rgba(23, 114, 69, 0.06);
}
.shipment-form-group input,
.shipment-form-group select {
  height: 44px;
  padding: 0 12px;
}
.shipment-form-group textarea {
  min-height: 120px;
  padding: 11px 12px;
  resize: vertical;
  line-height: 1.5;
}
.shipment-form-group small {
  margin-top: 6px;
  color: #888;
  font-size: 14px;
  line-height: 1.4;
}

/*
|--------------------------------------------------------------------------
| Status Preview
|--------------------------------------------------------------------------
*/
.shipment-status-preview {
  display: flex;
  align-items: flex-start;
  gap: 11px;
}
.shipment-status-preview__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}
.shipment-status-preview strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-status-preview span {
  display: block;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Order Preview
|--------------------------------------------------------------------------
*/
.shipment-order-preview {
  padding: 17px 18px;
}

.shipment-order-preview__top {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-bottom: 15px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
}

.shipment-order-preview__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 18px;
}

.shipment-order-preview__top strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-order-preview__top span {
  display: block;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Order Details
|--------------------------------------------------------------------------
*/
.shipment-order-preview__details {
  padding: 4px 0;
}
.shipment-order-preview__details > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(221, 221, 221, 0.6);
}
.shipment-order-preview__details > div:last-child {
  border-bottom: 0;
}
.shipment-order-preview__details > div span {
  color: #555555;
  font-size: 14px;
}
.shipment-order-preview__details > div strong {
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

.shipment-order-paid {
  color: #198754 !important;
}

/*
|--------------------------------------------------------------------------
| Order View
|--------------------------------------------------------------------------
*/
.shipment-order-view {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-top: 13px;
  margin-top: 4px;
  border-top: 1px solid rgba(221, 221, 221, 0.65);
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.shipment-order-view i {
  font-size: 16px;
}
.shipment-order-view:hover {
  text-decoration: underline;
}

/*
|--------------------------------------------------------------------------
| Checklist
|--------------------------------------------------------------------------
*/
.shipment-checklist {
  display: flex;
  flex-direction: column;
  padding: 8px 0;
}
.shipment-checklist > div {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 10px 18px;
}
.shipment-checklist > div i {
  color: #198754;
  font-size: 17px;
}
.shipment-checklist > div span {
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Responsive XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .shipment-create-grid {
    grid-template-columns: minmax(0, 1fr) 290px;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .shipment-create-grid {
    grid-template-columns: 1fr;
  }
  .shipment-create-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/*
|--------------------------------------------------------------------------
| Responsive MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .shipment-create-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .shipment-create-page__actions {
    width: 100%;
  }
  .shipment-create-btn {
    flex: 1;
  }
  .shipment-create-sidebar {
    grid-template-columns: 1fr;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .shipment-create-page__header h1 {
    font-size: 24px;
  }
  .shipment-create-page__header p {
    font-size: 14px;
  }
  .shipment-create-page__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .shipment-create-btn {
    width: 100%;
    padding: 0 9px;
  }
  .shipment-create-card__header {
    padding: 14px;
  }
  .shipment-create-card__body {
    padding: 14px;
  }
  .shipment-form-grid {
    grid-template-columns: 1fr;
    gap: 15px;
  }
  .shipment-form-group--full {
    grid-column: auto;
  }
  .shipment-order-preview {
    padding: 14px;
  }
}
