}

.shipment-summary__item {
  padding: 17px 18px;
  border-right: 1px solid rgba(221, 221, 221, 0.7);
}
.shipment-summary__item:last-child {
  border-right: 0;
}
.shipment-summary__item span {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.shipment-summary__item strong,
.shipment-summary__item a {
  display: block;
  color: #0D2B5A;
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
