}
.shipment-summary__item a {
  color: #177245;
}
.shipment-summary__item a:hover {
  text-decoration: underline;
}

.shipment-summary__success {
  color: #198754 !important;
}

/*
|--------------------------------------------------------------------------
| Main Grid
|--------------------------------------------------------------------------
*/
.shipment-details-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  align-items: start;
  gap: 20px;
}

.shipment-details-main,
.shipment-details-sidebar {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/*
|--------------------------------------------------------------------------
| Card
|--------------------------------------------------------------------------
*/
.shipment-details-card {
  overflow: hidden;
  border: 1px solid #ddd;
  border-radius: 11px;
  background: #fff;
}
.shipment-details-card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.7);
}
.shipment-details-card__header h2 {
  margin: 0;
  color: #0D2B5A;
  font-size: 18px;
  line-height: 1.4;
  font-weight: 700;
}
.shipment-details-card__header > div > span {
  display: block;
  margin-top: 3px;
  color: #555555;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Shipment Information
|--------------------------------------------------------------------------
*/
.shipment-info-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.shipment-info-item {
  padding: 16px 18px;
  border-right: 1px solid rgba(221, 221, 221, 0.6);
  border-bottom: 1px solid rgba(221, 221, 221, 0.6);
}
.shipment-info-item:nth-child(even) {
  border-right: 0;
}
.shipment-info-item:nth-last-child(-n+2) {
  border-bottom: 0;
}
.shipment-info-item > span:first-child {
  display: block;
  margin-bottom: 5px;
  color: #555555;
  font-size: 14px;
}
.shipment-info-item > strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.shipment-info-item > a {
  color: #177245;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
}
.shipment-info-item > a:hover {
  text-decoration: underline;
}

/*
|--------------------------------------------------------------------------
| Status
|--------------------------------------------------------------------------
*/
.shipment-status {
  display: inline-flex !important;
  align-items: center;
  gap: 6px;
  width: fit-content;
  min-height: 27px;
  padding: 4px 9px;
  border-radius: 20px;
  font-size: 14px !important;
  line-height: 1.3;
  font-weight: 600 !important;
}
.shipment-status i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.shipment-status--processing {
  background: rgba(13, 202, 240, 0.1);
  color: #087f99;
}
.shipment-status--pending {
  background: rgba(255, 193, 7, 0.12);
  color: #947000;
}

/*
|--------------------------------------------------------------------------
| Tracking
|--------------------------------------------------------------------------
*/
.shipment-tracking {
  padding: 20px 20px 20px 28px;
}

.shipment-tracking__item {
  position: relative;
  display: flex;
  gap: 13px;
  min-height: 82px;
}
.shipment-tracking__item:not(:last-child)::before {
  content: "";
  position: absolute;
  top: 30px;
  left: 13px;
  width: 1px;
  height: calc(100% - 5px);
  background: #ddd;
}
.shipment-tracking__item--completed:not(:last-child)::before {
  background: #198754;
}
.shipment-tracking__item--active:not(:last-child)::before {
  background: #ddd;
}

.shipment-tracking__indicator {
  position: relative;
  z-index: 2;
  width: 28px;
  height: 28px;
  flex: 0 0 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #ddd;
  border-radius: 50%;
  background: #fff;
  color: #999;
  font-size: 14px;
}
.shipment-tracking__item--completed .shipment-tracking__indicator {
  border-color: #198754;
  background: #198754;
  color: #fff;
}
.shipment-tracking__item--active .shipment-tracking__indicator {
  border-color: #177245;
  background: #177245;
  color: #fff;
}

.shipment-tracking__content {
  padding-bottom: 20px;
}
.shipment-tracking__content strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  line-height: 1.4;
  font-weight: 600;
}
.shipment-tracking__content span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}
.shipment-tracking__content small {
  display: block;
  color: #888;
  font-size: 14px;
}

/*
|--------------------------------------------------------------------------
| Address
|--------------------------------------------------------------------------
*/
.shipment-address {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding: 18px;
}

.shipment-address__icon {
  width: 42px;
  height: 42px;
  flex: 0 0 42px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}

.shipment-address__content {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.shipment-address__content strong {
  margin-bottom: 2px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-address__content span {
  color: #555555;
  font-size: 14px;
  line-height: 1.5;
}

/*
|--------------------------------------------------------------------------
| Items Table
|--------------------------------------------------------------------------
*/
.shipment-items-table-wrapper {
  width: 100%;
  overflow-x: auto;
}

.shipment-items-table {
  width: 100%;
  min-width: 650px;
  border-collapse: collapse;
}
.shipment-items-table th,
.shipment-items-table td {
  padding: 14px 18px;
  border-bottom: 1px solid rgba(221, 221, 221, 0.65);
  text-align: left;
