  font-size: 14px;
}
.shipment-items-table th {
  background: #F2F4F7;
  color: #555555;
  font-weight: 600;
  white-space: nowrap;
}
.shipment-items-table td {
  color: #555555;
}
.shipment-items-table tbody tr:last-child td {
  border-bottom: 0;
}

/*
|--------------------------------------------------------------------------
| Product
|--------------------------------------------------------------------------
*/
.shipment-product {
