/*
|--------------------------------------------------------------------------
| Carrier
|--------------------------------------------------------------------------
*/
.shipment-carrier-box {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 17px 18px;
}
.shipment-carrier-box__icon {
  width: 44px;
  height: 44px;
  flex: 0 0 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9px;
  background: rgba(23, 114, 69, 0.08);
  color: #177245;
  font-size: 19px;
}
.shipment-carrier-box strong {
  display: block;
  margin-bottom: 3px;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}
.shipment-carrier-box span {
  display: block;
  color: #555555;
  font-size: 14px;
}

.shipment-carrier-details {
  padding: 0 18px 17px;
}
.shipment-carrier-details > div {
  padding-top: 11px;
  margin-top: 11px;
  border-top: 1px solid rgba(221, 221, 221, 0.6);
}
.shipment-carrier-details > div span {
  display: block;
  margin-bottom: 4px;
  color: #555555;
  font-size: 14px;
}
.shipment-carrier-details > div strong {
  display: block;
  color: #0D2B5A;
  font-size: 14px;
  font-weight: 600;
}

/*
|--------------------------------------------------------------------------
| Quick Actions
|--------------------------------------------------------------------------
*/
.shipment-quick-actions {
  display: flex;
  flex-direction: column;
  padding: 7px 0;
}

.shipment-quick-action {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 18px;
  color: #555555;
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: 0.2s;
}
.shipment-quick-action i {
  width: 20px;
  color: #177245;
  font-size: 17px;
  text-align: center;
}
.shipment-quick-action:hover {
  background: rgba(23, 114, 69, 0.04);
  color: #177245;
}

/*
|--------------------------------------------------------------------------
| Note
|--------------------------------------------------------------------------
*/
.shipment-note {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 17px 18px;
}
.shipment-note i {
  margin-top: 2px;
  color: #177245;
  font-size: 17px;
}
.shipment-note p {
  margin: 0;
  color: #555555;
  font-size: 14px;
  line-height: 1.6;
}

/*
|--------------------------------------------------------------------------
| Responsive XL
|--------------------------------------------------------------------------
*/
@media (min-width: 1200px) and (max-width: 1399px) {
  .shipment-details-grid {
    grid-template-columns: minmax(0, 1fr) 300px;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive LG
|--------------------------------------------------------------------------
*/
@media (min-width: 992px) and (max-width: 1199px) {
  .shipment-details-grid {
    grid-template-columns: 1fr;
  }
  .shipment-details-sidebar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
/*
|--------------------------------------------------------------------------
| Responsive MD
|--------------------------------------------------------------------------
*/
@media (min-width: 768px) and (max-width: 991px) {
  .shipment-details-page__header {
    align-items: flex-start;
    flex-direction: column;
  }
  .shipment-details-page__actions {
    width: 100%;
  }
  .shipment-action-btn {
    flex: 1;
  }
  .shipment-details-title {
    align-items: flex-start;
    flex-direction: column;
  }
  .shipment-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .shipment-summary__item {
    border-right: 0;
    border-bottom: 1px solid rgba(221, 221, 221, 0.7);
  }
  .shipment-summary__item:nth-child(odd) {
    border-right: 1px solid rgba(221, 221, 221, 0.7);
  }
  .shipment-summary__item:nth-last-child(-n+2) {
    border-bottom: 0;
  }
  .shipment-details-sidebar {
    grid-template-columns: 1fr;
  }
}
/*
|--------------------------------------------------------------------------
| Responsive XS
|--------------------------------------------------------------------------
*/
@media (max-width: 767px) {
  .shipment-details-title h1 {
    font-size: 24px;
  }
  .shipment-summary {
    grid-template-columns: 1fr;
  }
  .shipment-summary__item {
    border-right: 0 !important;
    border-bottom: 1px solid rgba(221, 221, 221, 0.7);
  }
  .shipment-summary__item:last-child {
    border-bottom: 0;
  }
  .shipment-details-page__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
  .shipment-action-btn {
    width: 100%;
    padding: 0 9px;
  }
  .shipment-details-card__header {
    padding: 14px;
  }
  .shipment-info-grid {
    grid-template-columns: 1fr;
  }
  .shipment-info-item {
    border-right: 0 !important;
  }
  .shipment-info-item:last-child {
    border-bottom: 0;
  }
  .shipment-tracking {
    padding: 18px 14px 18px 18px;
  }
  .shipment-address {
    padding: 14px;
  }
  .shipment-customer {
    padding: 14px;
  }
  .shipment-customer-contact {
    padding: 0 14px 14px;
  }
  .shipment-carrier-box {
    padding: 14px;
  }
  .shipment-carrier-details {
    padding: 0 14px 14px;
  }
  .shipment-note {
    padding: 14px;
  }
}

